var baQuestions = [
    // --- CAPÍTULO 1: BACCM y Fundamentos BA (40 preguntas) ---
    { id: 701, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.1), ¿cuál es la relación correcta entre los seis conceptos básicos del BACCM?", options: ["Tienen jerarquía secuencial donde la Solución determina el Valor.", "Son iguales, interdependientes y necesarios; ninguno tiene mayor importancia y se definen mutuamente.", "El Contexto es el único elemento dinámico que subordina a las Partes Interesadas.", "La Necesidad y el Valor son opuestos conceptuales que se excluyen mutuamente."], correct: 1, explanation: "El modelo BACCM establece que los seis conceptos (Cambio, Necesidad, Solución, Parte interesada, Valor y Contexto) son iguales, interdependientes y necesarios.", pageRef: "BABOK v3, Cap. 2, Sec. 2.1", summary: ["BACCM: Los 6 conceptos centrales tienen igual importancia y se definen mutuamente."] },
    { id: 702, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.2), ¿cómo se define formalmente el análisis empresarial?", options: ["La práctica de habilitar el cambio en una empresa definiendo necesidades y recomendando soluciones que aporten valor.", "La codificación iterativa de requerimientos de software en metodologías ágiles.", "La supervisión contable de los estados financieros trimestrales de una corporación.", "El diseño exclusivo de diagramas de arquitectura de red y servidores en la nube."], correct: 0, explanation: "El análisis empresarial habilita el cambio definiendo necesidades y recomendando soluciones de valor.", pageRef: "BABOK v3, Cap. 1, Sec. 1.2", summary: ["Definición formal: Habilitar el cambio mediante la definición de necesidades y entrega de valor."] },
    { id: 703, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "En el esquema de clasificación de requisitos del BABOK v3 (Sec. 2.3), ¿qué describen los 'Requisitos Comerciales' (Business Requirements)?", options: ["Las capacidades y cualidades técnicas específicas de la interfaz de usuario.", "Las declaraciones de metas, objetivos y resultados estratégicos de por qué se inició un cambio.", "Las reglas temporales exclusivamente durante la migración de datos.", "Los contratos legales firmados con los proveedores de infraestructura."], correct: 1, explanation: "Los requisitos comerciales explican el 'por qué' del cambio a través de metas y objetivos corporativos.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos comerciales: Metas, objetivos y justificación estratégica del cambio."] },
    { id: 704, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿cómo define el estándar una 'Empresa' (Enterprise)?", options: ["Un sistema de una o más organizaciones y las soluciones que utilizan para perseguir objetivos comunes.", "Únicamente una entidad legal registrada con fines de lucro y acciones en la bolsa.", "Un equipo temporal de desarrollo de software que se disuelve al finalizar el sprint.", "Un departamento de recursos humanos aislado de la operación comercial."], correct: 0, explanation: "Una empresa abarca un sistema de una o más organizaciones y las soluciones empleadas para metas comunes.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Empresa: Sistema de organizaciones y soluciones con objetivos compartidos."] },
    { id: 705, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿cuál es la diferencia entre un 'Requisito' y un 'Diseño'?", options: ["Los requisitos se centran en la necesidad; los diseños se centran en la solución.", "Los requisitos son gerenciales y los diseños son código de programación.", "Los requisitos solo aplican en cascada y los diseños en marcos ágiles.", "No existe diferencia en el BABOK v3."], correct: 0, explanation: "El requisito representa la necesidad (el qué) y el diseño representa la solución utilizable (el cómo).", pageRef: "BABOK v3, Cap. 2, Sec. 2.5", summary: ["Requisito enfoca la necesidad; Diseño enfoca la solución."] },
    { id: 706, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿cómo se define el 'Riesgo' en el análisis de negocios?", options: ["El efecto de la incertidumbre sobre el valor de un cambio, una solución o la empresa.", "Un error en la sintaxis del código fuente detectado por el compilador.", "La demora inevitable en la entrega de hardware por parte de un proveedor.", "El costo financiero fijo de mantenimiento de servidores."], correct: 0, explanation: "El riesgo representa el efecto de la incertidumbre sobre el valor.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Riesgo: Efecto de la incertidumbre sobre el valor."] },
    { id: 707, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿qué subcategorías componen los 'Requisitos de la Solución'?", options: ["Requisitos funcionales y Requisitos no funcionales (calidad de servicio).", "Requisitos de proyecto y Requisitos de presupuesto.", "Requisitos de hardware y Requisitos de redes.", "Requisitos temporales y Requisitos permanentes."], correct: 0, explanation: "Los requisitos de la solución se dividen en funcionales (comportamiento) y no funcionales (cualidades o condiciones).", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos de solución: Funcionales y No funcionales."] },
    { id: 708, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿qué caracterizan a los 'Requisitos de Transición'?", options: ["Son capacidades temporales necesarias para facilitar el paso del estado actual al futuro, pero innecesarias después.", "Son los objetivos estratégicos globales de la junta directiva a 10 años.", "Describen el comportamiento operativo permanente del software en producción.", "Son las políticas contables de depreciación de activos."], correct: 0, explanation: "Los requisitos de transición son temporales y abordan temas como conversión de datos y capacitación.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos de transición: Temporales para facilitar la migración al estado futuro."] },
    { id: 709, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.3), ¿quién es considerado un 'Analista de Negocios'?", options: ["Cualquier persona que realice las tareas de análisis de negocios descritas en el BABOK, sin importar su cargo o rol.", "Exclusivamente el profesional con certificación CBAP activa.", "El gerente general o CEO de la compañía.", "El líder técnico del equipo de desarrollo de software."], correct: 0, explanation: "El rol no depende del título corporativo, sino de la ejecución de las tareas descritas en el BABOK.", pageRef: "BABOK v3, Cap. 1, Sec. 1.3", summary: ["Analista de negocios: Cualquier persona que ejecute tareas de BA, sin importar su título."] },
    { id: 710, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿qué abarca la 'Información de Análisis Comercial'?", options: ["Amplios y diversos conjuntos de información (resultados de elicitación, requisitos, diseños, opciones) analizados y transformados.", "Exclusivamente los documentos impresos en papel archivados en la oficina.", "Los registros de nómina y sueldos del personal corporativo.", "Los códigos fuente almacenados en los repositorios Git."], correct: 0, explanation: "Comprende toda la información en cualquier nivel de detalle usada como entrada o salida del BA.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Información de análisis comercial: Conjunto de datos, requisitos y diseños analizados."] },
    { id: 711, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.4), ¿cómo se define el concepto de 'Parte Interesada' (Stakeholder)?", options: ["Un grupo o individuo con una relación directa o indirecta con la iniciativa, el cambio o la empresa.", "Únicamente los accionistas mayoritarios con poder de voto en la junta directiva.", "Los desarrolladores externos contratados por honorarios temporales.", "Los usuarios finales que operan el sistema en producción exclusivamente."], correct: 0, explanation: "Una parte interesada puede ser cualquier persona o grupo afectado o que afecta la iniciativa.", pageRef: "BABOK v3, Cap. 2, Sec. 2.4", summary: ["Parte interesada: Individuo o grupo con relación o afectación en la iniciativa."] },
    { id: 712, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.1), ¿cómo interactúa el concepto 'Cambio' con la 'Necesidad'?", options: ["El cambio es la reacción a la necesidad para transformar el estado actual en uno que entregue valor.", "La necesidad destruye por completo la posibilidad de cambio en la organización.", "El cambio ocurre de forma aleatoria sin depender de las necesidades detectadas.", "La necesidad es consecuencia exclusiva de un cambio fallido."], correct: 0, explanation: "El cambio habilita la transformación para resolver necesidades y capturar valor.", pageRef: "BABOK v3, Cap. 2, Sec. 2.1", summary: ["Cambio y Necesidad: Transformación orientada a resolver necesidades."] },
    { id: 713, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿qué tipifican los 'Requisitos de los Proyectos'?", options: ["Las acciones, procesos o condiciones que el proyecto debe cumplir (ej. hitos, recursos, entregables de gestión).", "Las reglas matemáticas de los algoritmos de cifrado de datos.", "El diseño visual de los botones de la aplicación móvil.", "Los objetivos estratégicos globales de la junta directiva a 5 años."], correct: 0, explanation: "Los requisitos de proyecto guían la ejecución y gestión de la iniciativa para entregar la solución.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos de proyecto: Condiciones y procesos para gestionar la ejecución."] },
    { id: 714, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿qué comprende el 'Contexto' dentro del modelo BACCM?", options: ["Las circunstancias que rodean al cambio y que pueden influir, ser influenciadas o verse impactadas por él.", "Únicamente el presupuesto financiero asignado al departamento de sistemas.", "La ubicación geográfica física de los servidores centrales.", "El lenguaje de programación utilizado en el backend."], correct: 0, explanation: "El contexto abarca cultura, tecnología, infraestructura, competencia y entorno regulatorio.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Contexto: Circunstancias y entorno que rodean e impactan el cambio."] },
    { id: 715, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.1), ¿cómo se define el 'Valor' en el análisis de negocios?", options: ["El worth, importancia o utilidad de algo para una parte interesada dentro de un contexto.", "El costo monetario exacto de la infraestructura de hardware.", "El número total de horas invertidas por los desarrolladores.", "La cantidad de líneas de código escritas por sprint."], correct: 0, explanation: "El valor es subjetivo y representa la utilidad o ganancia percibida por los stakeholders.", pageRef: "BABOK v3, Cap. 2, Sec. 2.1", summary: ["Valor: Utilidad o importancia percibida por las partes interesadas."] },
    { id: 716, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.5), ¿qué competencias principales debe poseer un analista de negocios?", options: ["Pensamiento analítico, resolución de problemas, conocimiento de comportamiento, comunicación e interacción.", "Exclusivamente habilidades avanzadas de programación en C++ y ensamblador.", "Destreza en contabilidad fiscal y auditoría de estados financieros.", "Experiencia en instalación física de redes de fibra óptica."], correct: 0, explanation: "El BABOK destaca competencias conductuales, analíticas y de comunicación interpersonal.", pageRef: "BABOK v3, Cap. 1, Sec. 1.5", summary: ["Competencias BA: Pensamiento analítico, comunicación y resolución de problemas."] },
    { id: 717, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿cuál es la función de los 'Requisitos de Usuario'?", options: ["Describir las necesidades que los usuarios particulares deben poder satisfacer utilizando la solución.", "Establecer los impuestos corporativos anuales ante el gobierno.", "Definir la arquitectura de redes y protocolos de comunicación TCP/IP.", "Describir el código fuente de los microservicios."], correct: 0, explanation: "Los requisitos de usuario actúan como puente entre los requerimientos comerciales y los de la solución.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos de usuario: Capacidades que los usuarios necesitan realizar con la solución."] },
    { id: 718, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.5), ¿cómo influye el diseño en la comprensión de los requerimientos?", options: ["Los diseños ayudan a clarificar los requisitos al proporcionar representaciones tangibles de la solución.", "Los diseños reemplazan por completo la necesidad de documentar requerimientos.", "Los diseños confunden a las partes interesadas y retrasan los proyectos.", "No existe relación entre diseño y requerimiento."], correct: 0, explanation: "Los prototipos y diseños facilitan la validación y comprensión de las necesidades reales.", pageRef: "BABOK v3, Cap. 2, Sec. 2.5", summary: ["Diseño y requerimiento: Los diseños tangibles clarifican y validan necesidades."] },
    { id: 719, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.4), ¿qué es el 'Conocimiento de la Industria' (Industry Knowledge)?", options: ["La comprensión de las prácticas, normas, terminología y tendencias del sector donde opera la empresa.", "El dominio de herramientas de diseño gráfico vectorial.", "La capacidad de reparar equipos de cómputo defectuosos.", "El conocimiento de leyes de tránsito vehicular."], correct: 0, explanation: "Conocer la industria permite al BA comunicarse con fluidez y entender los impulsores de negocio.", pageRef: "BABOK v3, Cap. 1, Sec. 1.4", summary: ["Conocimiento de la industria: Entendimiento de normas, tendencias y sector."] },
    { id: 720, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿qué tipo de valor puede entregarse mediante una solución de análisis de negocios?", options: ["Valor potencial, valor real, valor tangible y valor intangible.", "Únicamente valor monetario en efectivo.", "Exclusivamente reducción de personal corporativo.", "Aumento de likes en redes sociales."], correct: 0, explanation: "El valor puede ser tanto potencial como realizado, abarcando aspectos tangibles e intangibles.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Tipos de valor: Potencial, real, tangible e intangible."] },
    { id: 721, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.1), ¿cómo se relacionan el 'Cambio' y la 'Solución'?", options: ["La solución es una manera específica de satisfacer una necesidad al habilitar un cambio.", "La solución impide que ocurra cualquier tipo de cambio futuro.", "El cambio y la solución son conceptos contradictorios.", "La solución antecede siempre al cambio organizativo."], correct: 0, explanation: "La solución implementada habilita el cambio necesario para generar valor.", pageRef: "BABOK v3, Cap. 2, Sec. 2.1", summary: ["Cambio y Solución: La solución habilita el cambio para satisfacer necesidades."] },
    { id: 722, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿qué evalúan los 'Requisitos No Funcionales' (Calidad de Servicio)?", options: ["Atributos de rendimiento, seguridad, disponibilidad, mantenibilidad y usabilidad del sistema.", "La cantidad de funciones aritméticas que realiza una calculadora.", "El número de reportes impresos generados al mes.", "La cantidad de empleados contratados."], correct: 0, explanation: "Los requisitos no funcionales definen condiciones de calidad operativa y restricciones.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos no funcionales: Atributos de calidad, rendimiento y seguridad."] },
    { id: 723, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.2), ¿cuál es el propósito principal del análisis empresarial en las organizaciones?", options: ["Guiar a las organizaciones hacia la consecución de sus metas mediante la recomendación de valor.", "Controlar la asistencia diaria del personal de oficina.", "Gestionar la contabilidad fiscal y declaración de impuestos.", "Desarrollar infraestructura de redes físicas."], correct: 0, explanation: "El foco central es la entrega de valor y el logro de metas estratégicas.", pageRef: "BABOK v3, Cap. 1, Sec. 1.2", summary: ["Propósito del BA: Guiar a la organización hacia sus metas generando valor."] },
    { id: 724, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.4), ¿por qué es crítico identificar correctamente a las partes interesadas?", options: ["Para asegurar que todas las perspectivas y necesidades relevantes sean consideradas en el análisis.", "Para excluirlas de las decisiones importantes del proyecto.", "Para reducir la cantidad de juntas de trabajo a cero.", "Para evitar la entrega de documentación técnica."], correct: 0, explanation: "Una identificación incompleta de stakeholders genera omisiones críticas de requerimientos.", pageRef: "BABOK v3, Cap. 2, Sec. 2.4", summary: ["Importancia de stakeholders: Asegurar cobertura integral de perspectivas y necesidades."] },
    { id: 725, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿qué define el concepto de 'Necesidad'?", options: ["Un problema u oportunidad a ser abordado que motiva el cambio.", "Un capricho temporal de los directivos de la empresa.", "Un contrato legal firmado con proveedores externos.", "Una línea de código fuente en un repositorio Git."], correct: 0, explanation: "La necesidad surge de un problema a resolver o una oportunidad a explotar.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Necesidad: Problema u oportunidad que impulsa el cambio."] },
    { id: 726, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.3), ¿cuándo comienza el trabajo de un analista de negocios en una iniciativa?", options: ["Desde las etapas tempranas de concepción y estrategia, hasta la evaluación posterior de la solución.", "Únicamente en el momento en que se inician las pruebas de aceptación de software.", "Exclusivamente cuando el proyecto ya ha fracasado en producción.", "Solo durante la firma del contrato comercial inicial."], correct: 0, explanation: "El BA interviene desde el análisis estratégico y la ideación hasta la evaluación del valor operativo.", pageRef: "BABOK v3, Cap. 1, Sec. 1.3", summary: ["Ciclo de participación del BA: Desde la estrategia inicial hasta la evaluación de valor."] },
    { id: 727, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.5), ¿cuál es la característica principal de un 'Diseño'?", options: ["Ser una representación utilizable de una solución que es potencialmente viable de construir.", "Ser una directriz de alta gerencia sin detalles operativos.", "Ser un documento estrictamente financiero y contable.", "Ser una ley gubernamental de cumplimiento obligatorio."], correct: 0, explanation: "El diseño muestra cómo se estructurará y comportará la solución para satisfacer el requisito.", pageRef: "BABOK v3, Cap. 2, Sec. 2.5", summary: ["Diseño: Representación utilizable y viable de la solución."] },
    { id: 728, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿cómo se relacionan los requisitos comerciales con los requisitos de la solución?", options: ["Los requisitos comerciales impulsan la creación de los requisitos de solución a través de un desglose estructurado.", "No guardan ninguna relación entre sí en los proyectos reales.", "Los requisitos de solución anulan por completo a los requisitos comerciales.", "Los requisitos comerciales son detalles técnicos de bajo nivel."], correct: 0, explanation: "Existe una jerarquía de trazabilidad donde los objetivos comerciales determinan los requerimientos de solución.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Relación de requisitos: Los comerciales guían y generan los de solución."] },
    { id: 729, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.5), ¿qué implica la habilidad de 'Pensamiento Sistémico' para un analista?", options: ["Comprender cómo las diferentes partes de una empresa interactúan y se afectan mutuamente como un sistema completo.", "Saber reparar componentes electrónicos de computadoras de escritorio.", "Programar sistemas operativos en lenguajes de bajo nivel.", "Diseñar la interfaz gráfica de páginas web."], correct: 0, explanation: "El pensamiento sistémico visualiza a la organización como un todo interconectado.", pageRef: "BABOK v3, Cap. 1, Sec. 1.5", summary: ["Pensamiento sistémico: Entender la organización y sus interacciones como un todo."] },
    { id: 730, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿qué factores determinan el 'Contexto' operativo de una organización?", options: ["Cultura corporativa, infraestructura tecnológica, procesos, regulaciones gubernamentales y mercado.", "Únicamente el clima meteorológico de la ciudad sede.", "El color de las paredes de las oficinas corporativas.", "La marca de los teléfonos celulares de los empleados."], correct: 0, explanation: "El contexto incluye todos los factores ambientales internos y externos que rodean la operación.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Factores de contexto: Cultura, tecnología, procesos, regulaciones y mercado."] },
    { id: 731, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.1), ¿por qué se afirma que los 6 conceptos del BACCM son 'núcleo'?", options: ["Porque definen el dominio y el alcance fundamental del conocimiento en el análisis empresarial.", "Porque son los únicos conceptos que se enseñan en universidades.", "Porque reemplazan a todas las metodologías de gestión de proyectos ágiles.", "Porque evitan la necesidad de documentar software."], correct: 0, explanation: "Constituyen el núcleo conceptual compartido por todos los profesionales del análisis de negocios.", pageRef: "BABOK v3, Cap. 2, Sec. 2.1", summary: ["Conceptos núcleo BACCM: Fundamento universal del análisis empresarial."] },
    { id: 732, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿qué característica define a los 'Requisitos Funcionales'?", options: ["Describen las capacidades, comportamientos e información que el sistema debe proporcionar.", "Establecen el presupuesto y los plazos contractuales de entrega.", "Definen la velocidad de descarga de la red de internet.", "Especifican las políticas de vacaciones del personal."], correct: 0, explanation: "Los requisitos funcionales detallan qué debe hacer el sistema funcionalmente.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Requisitos funcionales: Comportamientos y capacidades del sistema."] },
    { id: 733, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.3), ¿cuál es la importancia de la versatilidad metodológica para un Analista de Negocios?", options: ["Permite adaptar las tareas de análisis a contextos predictivos (cascada), adaptativos (ágiles) o híbridos.", "Obliga a la empresa a utilizar una sola metodología estricta sin excepciones.", "Elimina la necesidad de interactuar con los desarrolladores de software.", "Reduce los costos salariales del personal de gestión."], correct: 0, explanation: "La versatilidad metodológica asegura que el BA aplique las técnicas correctas según el marco de trabajo.", pageRef: "BABOK v3, Cap. 1, Sec. 1.3", summary: ["Versatilidad metodológica: Adaptar prácticas a entornos predictivos o ágiles."] },
    { id: 734, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿cómo se define el 'Valor Real' frente al 'Valor Potencial'?", options: ["El valor real es el valor ya experimentado y medido; el valor potencial es el valor estimado antes de implementar el cambio.", "El valor real es teórico y el potencial es contable.", "No existe diferencia conceptual entre ambos términos en el BABOK v3.", "El valor real solo aplica para empresas sin fines de lucro."], correct: 0, explanation: "El valor real se mide en la operación; el valor potencial es la expectativa proyectada.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Valor real vs potencial: Experiencia medida vs expectativa proyectada."] },
    { id: 735, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.4), ¿cómo influyen las partes interesadas en la definición del 'Valor'?", options: ["Diferentes partes interesadas pueden percibir y valorar de distinta manera los resultados de una misma solución.", "Todas las partes interesadas tienen exactamente la misma percepción de valor.", "El valor es determinado de forma unilateral por los auditores externos.", "Los usuarios finales no tienen opinión sobre el valor entregado."], correct: 0, explanation: "El valor es subjetivo y depende de las expectativas y prioridades de cada stakeholder.", pageRef: "BABOK v3, Cap. 2, Sec. 2.4", summary: ["Stakeholders y valor: Percepción subjetiva y diversa según cada parte interesada."] },
    { id: 736, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "According to BABOK v3 (Sec. 1.5), ¿qué rol juega la comunicación efectiva en la labor del analista?", options: ["Es el medio fundamental para elicitar, negociar, acordar y comunicar la información de análisis a la audiencia.", "Sirve únicamente para enviar correos electrónicos informativos de rutina.", "Reemplaza la necesidad de modelar procesos de negocio formalmente.", "Es una habilidad secundaria opcional para el rol técnico."], correct: 0, explanation: "La comunicación clara y bidireccional es vital para alinear entendimientos entre negocio y tecnología.", pageRef: "BABOK v3, Cap. 1, Sec. 1.5", summary: ["Comunicación efectiva: Medio clave para alinear entendimiento y negociar acuerdos."] },
    { id: 737, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.2), ¿qué impacto tiene la incertidumbre en los cambios empresariales?", options: ["Genera riesgos que pueden afectar negativamente o positivamente el valor final obtenido.", "Elimina por completo la necesidad de planificar actividades.", "Garantiza el éxito financiero absoluto de cualquier proyecto tecnológico.", "Impide que los requerimientos sean modificados."], correct: 0, explanation: "La incertidumbre se traduce en riesgos que deben ser evaluados y gestionados activamente.", pageRef: "BABOK v3, Cap. 2, Sec. 2.2", summary: ["Incertidumbre y riesgos: Genera variaciones que impactan el valor esperado."] },
    { id: 738, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.3), ¿en qué categoría se ubican las políticas de seguridad de la información corporativa?", options: ["Requisitos no funcionales (calidad de servicio y restricciones).", "Requisitos estrictamente comerciales sin impacto técnico.", "Requisitos de transición temporales de migración.", "Requisitos exclusivos de hardware de red."], correct: 0, explanation: "Las restricciones y normativas de seguridad forman parte de los requisitos no funcionales.", pageRef: "BABOK v3, Cap. 2, Sec. 2.3", summary: ["Políticas de seguridad: Clasificadas dentro de los requisitos no funcionales."] },
    { id: 739, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 1.2), ¿por qué es importante la independencia de criterio del analista de negocios?", options: ["Permite evaluar objetivamente las opciones y necesidades sin sesgos hacia ninguna solución preconcebida.", "Garantiza que el analista pueda tomar el control directivo de la compañía.", "Evita que los desarrolladores escriban código de programación.", "Elimina la participación de los patrocinadores en el proyecto."], correct: 0, explanation: "La objetividad ayuda a recomendar la solución óptima basada en datos y valor real.", pageRef: "BABOK v3, Cap. 1, Sec. 1.2", summary: ["Independencia de criterio: Objetividad frente a sesgos y soluciones preconcebidas."] },
    { id: 740, chapter: 1, chapterTitle: "Cap. 1: BACCM y Fundamentos BA", q: "Según el BABOK v3 (Sec. 2.5), ¿cuál es el beneficio principal de distinguir claramente entre requerimientos y diseños?", options: ["Evitar restricciones prematuras en la solución y enfocar primero el análisis en la necesidad real de negocio.", "Aumentar la cantidad de páginas de documentación técnica impresa.", "Reducir la velocidad de entrega del software en producción.", "Impedir que el equipo técnico proponga ideas creativas."], correct: 0, explanation: "Separar necesidad (qué) de solución (cómo) previene sesgos tecnológicos tempranos.", pageRef: "BABOK v3, Cap. 2, Sec. 2.5", summary: ["Beneficio de distinción: Evitar restricciones prematuras y enfocar la necesidad real."] },

    // --- CAPÍTULO 2: Planificación y Seguimiento del Análisis Empresarial (40 preguntas) ---
    { id: 741, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿cuál es el propósito principal de la tarea 'Planificar el enfoque de análisis de negocios'?", options: ["Definir un método apropiado para llevar a cabo actividades de análisis de negocios.", "Diseñar la interfaz gráfica de usuario en Figma.", "Ejecutar pruebas automatizadas en tuberías de CI/CD.", "Contratar al personal de desarrollo externo."], correct: 0, explanation: "Define el método y enfoque general para realizar el trabajo de análisis empresarial.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1", summary: ["Enfoque de análisis empresarial: Método y planificación de tareas."] },
    { id: 742, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿qué define la tarea 'Plan de análisis de negocios Gobernanza'?", options: ["Cómo se toman las decisiones sobre requisitos y diseños, incluidas revisiones, control de cambios, aprobaciones y priorización.", "El presupuesto salarial anual de la empresa.", "La velocidad de los servidores en la nube.", "Los lineamientos de marketing digital corporativo."], correct: 0, explanation: "Establece los tomadores de decisiones, control de cambios, aprobaciones y priorización.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Gobernanza BA: Decisiones, control de cambios y aprobaciones."] },
    { id: 743, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿qué caracteriza a un enfoque de planificación 'predictivo' frente a uno 'adaptativo'?", options: ["El predictivo busca minimizar incertidumbre inicial con alcances formales; el adaptativo prioriza entregas iterativas y valor temprano.", "El predictivo elimina la documentación y el adaptativo exige contratos en cascada.", "El predictivo se usa solo en mantenimiento y el adaptativo en auditorías fiscales.", "No hay diferencias en los entregables de gestión."], correct: 0, explanation: "Los enfoques predictivos buscan control y minimizar riesgos iniciales; los adaptativos priorizan iteraciones rápidas.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1.4", summary: ["Enfoques: Predictivo (control/formalidad) vs Adaptativo (iterativo/valor rápido)."] },
    { id: 744, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué implica la tarea 'Planificar la participación de las partes interesadas'?", options: ["Identificar a las partes interesadas, analizar sus características y definir los mejores enfoques de colaboración y comunicación.", "Asignar tareas de desarrollo de software a los ingenieros junior.", "Establecer los precios de venta de los productos al público final.", "Comprar licencias de software corporativo."], correct: 0, explanation: "Implica análisis exhaustivo de stakeholders para estructurar la colaboración y comunicación efectiva.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2", summary: ["Participación de stakeholders: Análisis de características y definición de colaboración."] },
    { id: 745, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿qué describe el 'Plan de Gestión de Información de Análisis de Negocios'?", options: ["Cómo se captura, almacena, organiza e integra la información desarrollada por los analistas (requisitos y diseños).", "Las políticas de seguridad para el acceso a las redes sociales de la empresa.", "Los respaldos físicos de las computadoras portátiles de la oficina.", "El directorio telefónico y de correo electrónico del personal."], correct: 0, explanation: "Define cómo se organiza, almacena, estructura y accede a la información de análisis a largo plazo.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Gestión de información BA: Organización, almacenamiento y acceso a artefactos."] },
    { id: 746, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿cuál es el objetivo de 'Identificar mejoras en el rendimiento del análisis comercial'?", options: ["Evaluar el trabajo de análisis comercial y planificar la mejora de los procesos cuando sea necesario.", "Despedir al personal de análisis de baja productividad.", "Aumentar el número de juntas diarias de seguimiento.", "Reducir los salarios del equipo técnico."], correct: 0, explanation: "Busca evaluar el desempeño del análisis y proponer acciones preventivas, correctivas o de mejora.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Mejora de rendimiento BA: Evaluar procesos y aplicar acciones correctivas/preventivas."] },
    { id: 747, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), al analizar las actitudes de las partes interesadas, ¿qué se busca identificar?", options: ["Cómo perciben los objetivos de la iniciativa, el cambio propuesto y el análisis de negocios en general.", "Su color favorito y sus pasatiempos personales fuera del trabajo.", "Su nivel de habilidad en programación orientada a objetos.", "Su preferencia de marcas comerciales de computadoras."], correct: 0, explanation: "Identificar actitudes permite anticipar resistencias y planificar estrategias de colaboración adecuadas.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2.4", summary: ["Actitudes de stakeholders: Comprender percepción para gestionar la cooperación."] },
    { id: 748, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿qué componentes principales se consideran al diseñar un 'Proceso de Control de Cambios'?", options: ["Pasos para proponer cambios, estimaciones de costo/tiempo, beneficios, riesgos y vías de acción.", "La selección de colores corporativos para el logotipo del software.", "El horario de entrada y salida de los empleados de soporte técnico.", "La cotización de acciones en la bolsa de valores."], correct: 0, explanation: "Un proceso de control de cambios evalúa solicitudes detallando costos, beneficios, riesgos y aprobaciones.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3.4", summary: ["Control de cambios: Evaluación de costos, beneficios, impactos y riesgos."] },
    { id: 749, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿qué describe el 'Nivel de Abstracción' en la gestión de información?", options: ["La amplitud y profundidad de la información proporcionada, variando desde conceptual hasta muy detallada.", "El grado de complejidad del código fuente en lenguaje ensamblador.", "La distancia geográfica entre las oficinas centrales y las sucursales.", "El nivel de cifrado de seguridad en las bases de datos."], correct: 0, explanation: "El nivel de abstracción adapta la amplitud y profundidad de la información según el rol de la audiencia.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4.4", summary: ["Nivel de abstracción: Amplitud y profundidad adaptada a la audiencia."] },
    { id: 750, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿qué tipos de medidas se emplean para evaluar el rendimiento del análisis comercial?", options: ["Medidas cuantitativas (fechas, métricas de ciclos) y cualitativas (precisión, retroalimentación de pares).", "Únicamente el peso físico de la documentación impresa producida.", "La cantidad de tazas de café consumidas durante las reuniones.", "El número de líneas de código escritas por el analista."], correct: 0, explanation: "El rendimiento del BA se evalúa mediante métricas cuantitativas y cualitativas de precisión y oportunidad.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5.2", summary: ["Medidas de rendimiento BA: Cuantitativas y cualitativas."] },
    { id: 751, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿qué factores determinan la selección del enfoque de análisis de negocios?", options: ["La complejidad del problema, la incertidumbre, el tamaño de la organización y la cultura corporativa.", "Exclusivamente el costo de las licencias de software.", "El número de empleados que trabajan remotamente.", "La cantidad de servidores físicos disponibles."], correct: 0, explanation: "La elección metodológica depende de la naturaleza del problema, incertidumbre y contexto corporativo.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1.4", summary: ["Selección de enfoque: Influenciada por complejidad, incertidumbre y cultura."] },
    { id: 752, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué es una 'Matriz de Poder e Interés' en la planificación de stakeholders?", options: ["Una herramienta para clasificar a las partes interesadas según su grado de autoridad y su nivel de involucramiento.", "Una tabla contable para calcular el sueldo de los gerentes.", "Un diagrama de redes para conectar computadoras de oficina.", "Una lista de códigos de programación backend."], correct: 0, explanation: "Ayuda a definir la estrategia de comunicación y gestión requerida para cada grupo de interés.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2.4", summary: ["Matriz poder/interés: Clasificación de stakeholders para definir gestión."] },
    { id: 753, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿quiénes participan típicamente en la definición de la gobernanza de requisitos?", options: ["El analista de negocios en colaboración con los patrocinadores y tomadores de decisiones clave.", "Únicamente los desarrolladores junior de software.", "Los clientes externos que compran el producto final.", "El personal de limpieza de la empresa."], correct: 0, explanation: "La gobernanza requiere acuerdo entre quienes deciden y quienes ejecutan el análisis.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Gobernanza de requisitos: Acordada entre analistas, patrocinadores y tomadores de decisiones."] },
    { id: 754, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿qué aspecto abarca la 'Trazabilidad de la Información' en el plan de gestión?", options: ["Cómo se relacionarán y rastrearán los requerimientos, diseños y elementos del proyecto entre sí.", "Cómo se transportarán los equipos de cómputo entre sucursales.", "Cómo se archivarán los recibos de nómina de los empleados.", "Cómo se conectarán los cables de red en el centro de datos."], correct: 0, explanation: "Define las reglas y herramientas para mantener el linaje de los artefactos de análisis.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Trazabilidad de información: Reglas para vincular requisitos y diseños."] },
    { id: 755, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿qué se hace con las lecciones aprendidas identificadas en el rendimiento del BA?", options: ["Se documentan y se utilizan para mejorar los procesos y prácticas de análisis en futuros proyectos.", "Se eliminan para no dejar constancia de los errores cometidos.", "Se entregan exclusivamente al departamento fiscal de la empresa.", "Se publican en redes sociales corporativas sin filtro."], correct: 0, explanation: "Las lecciones aprendidas alimentan la mejora continua del rendimiento organizativo.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Lecciones aprendidas: Insumo fundamental para la mejora continua del análisis."] },
    { id: 756, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿cómo se adapta un enfoque de análisis híbrido?", options: ["Combinando prácticas predictivas para ciertos componentes y adaptativas/ágiles para otros.", "Utilizando únicamente metodologías de desarrollo en cascada estricta.", "Eliminando cualquier tipo de documentación o modelo formal.", "Reemplazando al analista de negocios por inteligencia artificial."], correct: 0, explanation: "Los enfoques híbridos mezclan lo mejor de los mundos predictivo y ágil según la necesidad.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1", summary: ["Enfoque híbrido: Combinación de prácticas predictivas y adaptativas."] },
    { id: 757, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué rol cumple la autoridad de las partes interesadas en el análisis?", options: ["Determina su capacidad para aprobar decisiones, asignar presupuestos o vetar cambios en los requisitos.", "Define exclusivamente su horario de almuerzo en la oficina.", "Establece su velocidad de escritura en el teclado.", "Indica su preferencia de lenguaje de programación."], correct: 0, explanation: "Conocer la autoridad de los stakeholders evita bloqueos en la aprobación de entregables.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2", summary: ["Autoridad de stakeholders: Capacidad para aprobar decisiones y vetar cambios."] },
    { id: 758, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿por qué es importante un flujo claro de control de cambios?", options: ["Para evitar cambios descontrolados ('scope creep') que desvíen el presupuesto y los plazos.", "Para retrasar los proyectos indefinidamente sin justificación.", "Para impedir que los clientes hablen con los desarrolladores.", "Para duplicar el costo operativo de la empresa."], correct: 0, explanation: "El control de cambios protege el alcance y asegura que toda modificación aporte valor real.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Control de cambios: Previene el 'scope creep' y protege el valor del proyecto."] },
    { id: 759, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿qué criterios definen la elección de herramientas de gestión de información BA?", options: ["Accesibilidad, facilidad de uso, capacidad de integración, seguridad y costos asociados.", "El color y diseño visual de la interfaz de la herramienta.", "La nacionalidad de los creadores del software.", "El tamaño físico de los servidores donde se aloja."], correct: 0, explanation: "Las herramientas deben garantizar seguridad, acceso oportuno e integración con el equipo.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Herramientas de gestión: Criterios de accesibilidad, seguridad e integración."] },
    { id: 760, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿qué indicador cualitativo evalúa la precisión del análisis comercial?", options: ["El grado en que los requisitos y diseños satisfacen las necesidades reales sin requerir retrabajo excesivo.", "El número total de páginas escritas en un documento de texto.", "La cantidad de reuniones realizadas por semana.", "El peso físico de la documentación impresa."], correct: 0, explanation: "La calidad se mide en la efectividad y bajo nivel de defectos o retrabajo de los requerimientos.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Precisión del análisis: Evaluada por la satisfacción de necesidades sin retrabajo."] },
    { id: 761, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿quién aprueba formalmente el plan de enfoque de análisis de negocios?", options: ["Los patrocinadores y las partes interesadas clave con autoridad de decisión.", "Únicamente los ingenieros de pruebas de software.", "El personal de soporte técnico de nivel 1.", "Cualquier empleado de la compañía sin importar su cargo."], correct: 0, explanation: "El plan de enfoque requiere validación de los tomadores de decisiones para asegurar alineación.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1", summary: ["Aprobación de enfoque: Validada por patrocinadores y stakeholders clave."] },
    { id: 762, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué se evalúa en el análisis de 'Influencia' de las partes interesadas?", options: ["Su capacidad para impactar positivamente o negativamente en los resultados de la iniciativa.", "Su habilidad para redactar código fuente en Java.", "Su conocimiento de contabilidad fiscal corporativa.", "Su velocidad al utilizar hojas de cálculo."], correct: 0, explanation: "La influencia mide el poder de un stakeholder para acelerar, bloquear o transformar el proyecto.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2", summary: ["Influencia de stakeholders: Capacidad de impacto en los resultados de la iniciativa."] },
    { id: 763, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿qué establece el proceso de priorización dentro de la gobernanza?", options: ["Los criterios y la frecuencia con la que se evaluará la prioridad de los requisitos y diseños.", "El salario mensual de los analistas de negocio.", "La velocidad de conexión a internet de la oficina.", "El horario de las reuniones de café."], correct: 0, explanation: "La gobernanza define cómo y cuándo se prioriza el backlog o conjunto de requerimientos.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Proceso de priorización: Criterios y periodicidad para ordenar requerimientos."] },
    { id: 764, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿cómo se gestionan los derechos de acceso a la información de análisis?", options: ["Estableciendo permisos según el rol y la necesidad de conocer ('need-to-know') de cada parte interesada.", "Permitiendo acceso total e irrestricto a todo el personal de la empresa y externos.", "Ocultando la información a todos los miembros del equipo de desarrollo.", "Imprimiendo copias físicas en papel para quemarlas después."], correct: 0, explanation: "La seguridad y control de accesos protegen la confidencialidad de la información comercial.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Derechos de acceso: Controlados por roles y principio de necesidad de conocer."] },
    { id: 765, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿qué acción correctiva se puede tomar si el análisis comercial sufre retrasos crónicos?", options: ["Ajustar la asignación de recursos, simplificar procesos de aprobación o redefinir la planificación de tareas.", "Aumentar las horas de trabajo obligatorio sin previo aviso.", "Despedir a todo el equipo técnico de desarrollo de software.", "Eliminar por completo las fases de análisis."], correct: 0, explanation: "Las acciones correctivas optimizan los flujos de trabajo del BA ante desviaciones.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Acción correctiva por retrasos: Ajustar recursos y optimizar flujos de análisis."] },
    { id: 766, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿qué relación existe entre la incertidumbre y la formalidad del plan BA?", options: ["A mayor incertidumbre, se requieren enfoques de análisis más adaptativos e iterativos en lugar de rígidos.", "A mayor incertidumbre, se exige más documentación estricta e inflexible.", "La incertidumbre no afecta en absoluto la planificación del análisis.", "La incertidumbre elimina la necesidad de planificar."], correct: 0, explanation: "Los entornos altamente inciertos se benefician de la adaptabilidad y ciclos cortos.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1", summary: ["Incertidumbre y formalidad: Alta incertidumbre requiere enfoques adaptativos."] },
    { id: 767, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué tipo de canales de comunicación deben planificarse para las partes interesadas?", options: ["Canales formales e informales adaptados a las preferencias y necesidades de la audiencia.", "Únicamente llamadas telefónicas de emergencia a medianoche.", "Exclusivamente cartas impresas enviadas por correo postal tradicional.", "Solo mensajes cifrados en código Morse."], correct: 0, explanation: "Diversificar canales asegura que la información fluya eficazmente hacia todos los perfiles.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2", summary: ["Canales de comunicación: Formales e informales adaptados a la audiencia."] },
    { id: 768, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿qué ocurre cuando no se define una gobernanza clara en los proyectos?", options: ["Confusión en la toma de decisiones, disputas por el alcance y retrasos severos en las aprobaciones.", "Aumento inmediato de la productividad y felicidad del equipo.", "Reducción automática de los costos de desarrollo.", "Entrega perfecta del software en la mitad del tiempo."], correct: 0, explanation: "La ausencia de gobernanza genera ambigüedad y conflictos sobre quién decide qué.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Ausencia de gobernanza: Genera confusión, disputas de alcance y retrasos."] },
    { id: 769, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿por qué es importante la reutilización de información de análisis?", options: ["Ahorra tiempo y esfuerzo al aprovechar modelos, reglas y requisitos probados en iniciativas anteriores.", "Obliga a repetir el mismo trabajo desde cero en cada nuevo proyecto.", "Incurre en mayores costos operativos sin ningún beneficio.", "Invalida la documentación histórica de la empresa."], correct: 0, explanation: "La reutilización optimiza los tiempos del BA y asegura consistencia corporativa.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Reutilización de información: Ahorra esfuerzo y garantiza consistencia histórica."] },
    { id: 770, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿cómo contribuye el seguimiento del rendimiento del BA a la madurez organizacional?", options: ["Identificando fortalezas y debilidades recurrentes para institucionalizar mejores prácticas corporativas.", "Aumentando la burocracia y los trámites administrativos internos.", "Disminuyendo la calidad de los entregables de software.", "Ocultando los errores operativos a la junta directiva."], correct: 0, explanation: "Analizar el rendimiento permite madurar los procesos internos de análisis empresarial.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Madurez organizacional: Potenciada mediante la identificación de buenas prácticas."] },
    { id: 771, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿qué elementos incluye el presupuesto de análisis de negocios en la planificación?", options: ["Tiempo del personal, costos de herramientas, capacitación y recursos necesarios para ejecutar las tareas BA.", "Únicamente el costo de los equipos de cómputo portátiles.", "El presupuesto de marketing y publicidad externa de la empresa.", "Los gastos de cafetería de la oficina."], correct: 0, explanation: "El presupuesto abarca todos los recursos humanos, tecnológicos y temporales del análisis.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1", summary: ["Presupuesto BA: Recursos de tiempo, herramientas y personal para el análisis."] },
    { id: 772, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué indica una actitud de 'resistencia' en una parte interesada clave?", options: ["Oposición al cambio propuesto que debe ser gestionada mediante comunicación y participación activa.", "Un apoyo incondicional y absoluto a los objetivos del proyecto.", "Una falta total de interés sin impacto en la iniciativa.", "Un deseo de liderar el equipo de desarrollo técnico."], correct: 0, explanation: "La resistencia requiere estrategias de gestión de cambio para mitigar riesgos de boicot o fracaso.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2", summary: ["Resistencia de stakeholders: Requiere gestión activa y comunicación para alinear."] },
    { id: 773, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿quiénes son los 'aprobadores' dentro del proceso de gobernanza?", options: ["Partes interesadas con la autoridad formal para aceptar los requisitos, diseños o cambios de alcance.", "Cualquier observador externo sin relación con la empresa.", "Los analistas junior que redactan la documentación.", "Los usuarios que operan el sistema de manera eventual."], correct: 0, explanation: "Los aprobadores tienen la responsabilidad y autoridad de dar luz verde a los entregables.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Aprobadores en gobernanza: Stakeholders con autoridad formal de aceptación."] },
    { id: 774, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿qué función cumple un repositorio centralizado de requisitos?", options: ["Garantizar una fuente única de verdad ('single source of truth') accesible y actualizada para todo el equipo.", "Duplicar la información en múltiples archivos dispersos sin control.", "Ocultar los cambios recientes a los desarrolladores.", "Eliminar la trazabilidad entre requerimientos y diseños."], correct: 0, explanation: "Un repositorio central previene inconsistencias y asegura que todos consulten la versión vigente.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Repositorio centralizado: Fuente única de verdad y control de versiones vigentes."] },
    { id: 775, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿qué métrica cuantitativa se puede aplicar al evaluar el trabajo de elicitación?", options: ["El número de requerimientos elicitados por sesión o el tiempo promedio por entrevista.", "La felicidad subjetiva de los participantes en la reunión.", "El color de la ropa usada por los asistentes.", "El número de tazas de café consumidas."], correct: 0, explanation: "Las métricas cuantitativas miden volumen, tiempos y rendimientos medibles.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Métrica cuantitativa en elicitación: Volumen de requerimientos y tiempos por sesión."] },
    { id: 776, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.1), ¿por qué es dinámico el proceso de planificación del análisis de negocios?", options: ["Porque las condiciones del proyecto, los riesgos y las necesidades evolucionan continuamente a lo largo del tiempo.", "Porque se realiza una sola vez al inicio y nunca más se vuelve a revisar.", "Porque depende exclusivamente de los caprichos del cliente.", "Porque cambia de responsable cada semana obligatoriamente."], correct: 0, explanation: "La planificación se ajusta de manera iterativa conforme avanza la iniciativa y se descubre nueva información.", pageRef: "BABOK v3, Cap. 3, Sec. 3.1", summary: ["Planificación dinámica: Se ajusta iterativamente ante la evolución del proyecto."] },
    { id: 777, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.2), ¿qué se busca lograr al involucrar tempranamente a las partes interesadas?", options: ["Obtener su apoyo, alinear expectativas y prevenir sorpresas o rechazos en etapas avanzadas.", "Demorar el inicio del desarrollo técnico innecesariamente.", "Incrementar los costos operativos del proyecto de forma injustificada.", "Evitar la entrega de documentación formal."], correct: 0, explanation: "El compromiso temprano fomenta la apropiación del cambio y reduce resistencias posteriores.", pageRef: "BABOK v3, Cap. 3, Sec. 3.2", summary: ["Involucramiento temprano: Alinea expectativas y reduce resistencia al cambio."] },
    { id: 778, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.3), ¿qué debe incluir un registro de solicitudes de cambio?", options: ["Descripción del cambio, solicitante, fecha, impacto estimado, estado de aprobación y justificación.", "Únicamente el nombre de la persona que rechazó el cambio.", "El código fuente modificado en formato binario.", "La lista de correo electrónico de todos los empleados."], correct: 0, explanation: "El registro de cambios mantiene la trazabilidad histórica de todas las modificaciones solicitadas.", pageRef: "BABOK v3, Cap. 3, Sec. 3.3", summary: ["Registro de solicitudes de cambio: Historial de impactos, estados y justificaciones."] },
    { id: 779, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.4), ¿cómo se maneja la estructura de la información de análisis comercial?", options: ["Organizándola en jerarquías lógicas, paquetes temáticos o modelos estructurados según la audiencia.", "Guardando todos los datos en un solo archivo de texto plano sin orden.", "Escribiendo los requerimientos en códigos secretos aleatorios.", "Imprimiendo los documentos en desorden."], correct: 0, explanation: "Una estructura clara facilita la lectura, comprensión y mantenimiento de la información.", pageRef: "BABOK v3, Cap. 3, Sec. 3.4", summary: ["Estructura de información: Organización lógica en paquetes y modelos accesibles."] },
    { id: 780, chapter: 2, chapterTitle: "Cap. 2: Planificación y Seguimiento BA", q: "Según el BABOK v3 (Sec. 3.5), ¿qué beneficio aporta revisar periódicamente el rendimiento del análisis comercial?", options: ["Detectar cuellos de botella operativos a tiempo y aplicar mejoras antes de que afecten el proyecto global.", "Aumentar la carga burocrática del equipo sin propósito útil.", "Justificar despidos masivos de personal técnico.", "Retrasar deliberadamente las entregas del software."], correct: 0, explanation: "La revisión oportuna asegura la eficiencia y calidad continua del trabajo de análisis.", pageRef: "BABOK v3, Cap. 3, Sec. 3.5", summary: ["Revisión de rendimiento BA: Detección temprana de cuellos de botella y mejora continua."] },

    // --- CAPÍTULO 3: Obtención y Colaboración (40 preguntas) ---
    { id: 781, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿cuál es el propósito principal de la tarea 'Prepárese para la elicitación'?", options: ["Comprender el alcance de la actividad, seleccionar técnicas apropiadas y planificar materiales y recursos de apoyo.", "Desplegar el sistema en producción un viernes por la tarde.", "Realizar pruebas de estrés a la base de datos relacional.", "Calcular los impuestos corporativos de la organización."], correct: 0, explanation: "Establece el alcance, selecciona técnicas y prepara la logística de elicitación.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Preparación de elicitación: Alcance, técnicas y logística."] },
    { id: 782, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿para qué sirve la tarea 'Confirmar resultados de elicitación'?", options: ["Verificar la precisión y coherencia de la información recopilada durante una sesión frente a otras fuentes.", "Borrar los requerimientos obsoletos del repositorio del proyecto.", "Evaluar el desempeño financiero trimestral de la empresa.", "Asignar bonos de productividad al equipo directivo."], correct: 0, explanation: "Verifica precisión, detecta errores, omisiones o conflictos antes de comprometer recursos.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Confirmar elicitación: Verificar precisión y coherencia."] },
    { id: 783, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿cuáles son los tres tipos comunes de elicitación?", options: ["Colaborativo, Investigación y Experimentos.", "Casélstico, Estático y Dinámico.", "Funcional, No funcional y de Transición.", "Predictivo, Adaptativo e Híbrido."], correct: 0, explanation: "El BABOK categoriza la elicitación en colaborativa (interacción directa), investigación (estudio sistemático) y experimentos.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2.2", summary: ["Tipos de elicitación: Colaborativa, Investigación y Experimentos."] },
    { id: 784, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿qué busca la tarea 'Comunicar información de análisis comercial'?", options: ["Garantizar que las partes interesadas tengan una comprensión compartida de la información de análisis comercial.", "Enviar correos masivos de publicidad a clientes externos de la competencia.", "Publicar notas de prensa en periódicos locales sobre el software.", "Reemplazar los contratos legales por mensajes de texto."], correct: 0, explanation: "Asegura una comprensión compartida y bidireccional de la información con la audiencia adecuada.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Comunicar información BA: Comprensión compartida con la audiencia."] },
    { id: 785, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿cuál es el objetivo de 'Gestionar la colaboración de las partes interesadas'?", options: ["Alentar a las partes interesadas a trabajar hacia un objetivo común y mantener relaciones de confianza.", "Imponer órdenes estrictas sin derecho a réplica ni discusión.", "Aislar al equipo técnico de cualquier contacto con el negocio.", "Reducir la participación del patrocinador al mínimo absoluto."], correct: 0, explanation: "Fomenta la colaboración activa, el libre flujo de ideas y mitiga reacciones negativas al cambio.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Colaboración de stakeholders: Trabajar hacia un objetivo común con confianza."] },
    { id: 786, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿qué elementos abarca la configuración de la logística de elicitación?", options: ["Objetivos, participantes, roles, agenda, recursos programados, ubicaciones y canales de comunicación.", "El diseño de la base de datos relacional en SQL Server.", "La arquitectura de redes de área local (LAN).", "La selección de lenguajes de programación backend."], correct: 0, explanation: "La logística incluye definir objetivos, roles, recursos, agendas, ubicaciones y canales.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1.4", summary: ["Logística de elicitación: Objetivos, roles, agenda y recursos."] },
    { id: 787, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿en qué consiste la elicitación por 'Investigación'?", options: ["Descubrir y estudiar sistemáticamente información de materiales o fuentes que no son directamente conocidas por las partes interesadas.", "Preguntar directamente opiniones subjetivas en una entrevista informal.", "Realizar pruebas clínicas en laboratorios farmacéuticos.", "Instalar cámaras de vigilancia en las oficinas."], correct: 0, explanation: "La investigación profundiza en documentos, datos históricos y fuentes secundarias de manera sistemática.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2.2", summary: ["Elicitación por investigación: Estudio sistemático de fuentes y materiales."] },
    { id: 788, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿cómo se detectan típicamente las inconsistencias en los resultados de elicitación?", options: ["Cuando los analistas de negocio desarrollan especificaciones y modelos que revelan contradicciones.", "Cuando el sistema operativo arroja un error de memoria RAM.", "Cuando el departamento legal rechaza pagar la factura eléctrica.", "Cuando los servidores físicos se sobrecalientan."], correct: 0, explanation: "Las contradicciones y lagunas emergen al modelar y estructurar la información obtenida.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3.2", summary: ["Detección de inconsistencias: Emerge al desarrollar especificaciones y modelos."] },
    { id: 789, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿qué formatos pueden tener los 'Paquetes de Información' de análisis comercial?", options: ["Documentación formal (plantillas estándar), documentación informal y presentaciones.", "Exclusivamente código ejecutable en formato binario.", "Grabaciones de audio en casetes de cinta magnética.", "Diagramas dibujados a mano en servilletas de papel."], correct: 0, explanation: "Los paquetes de comunicación se adaptan en formatos formales, informales o presentaciones ejecutivas.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4.4", summary: ["Paquetes de información: Formal, informal y presentaciones."] },
    { id: 790, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿cuáles son efectos perjudiciales de una mala relación con las partes interesadas?", options: ["Falta de información de calidad, resistencia al cambio, falta de apoyo y omisión de datos críticos.", "Aumento inmediato de la velocidad de entrega en los sprints ágiles.", "Reducción de los costos operativos de la empresa.", "Optimización automática del código de software."], correct: 0, explanation: "Las malas relaciones generan desconfianza, resistencia y pésima calidad de información.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5.2", summary: ["Efectos de malas relaciones: Falta de calidad, resistencia y resistencia al cambio."] },
    { id: 791, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿qué se debe considerar al seleccionar las técnicas de elicitación?", options: ["El tipo de información requerida, la disponibilidad de los participantes, el presupuesto y el contexto.", "Únicamente el color del logotipo de la empresa.", "El número de empleados que trabajan en el área financiera.", "La marca de los equipos de cómputo."], correct: 0, explanation: "La selección de técnicas debe alinearse con los objetivos y la disponibilidad de los stakeholders.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Selección de técnicas: Basada en información requerida, participantes y contexto."] },
    { id: 792, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿qué caracteriza a los 'Experimentos' como técnica de elicitación?", options: ["Permiten descubrir información sobre necesidades o comportamientos mediante pruebas controladas y prototipos.", "Consisten en adivinar el futuro mediante la lectura de cartas.", "Son auditorías contables obligatorias de impuestos.", "Implican instalar redes de fibra óptica."], correct: 0, explanation: "Los experimentos validan hipótesis y descubren necesidades mediante la práctica directa.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2", summary: ["Elicitación por experimentos: Pruebas controladas para descubrir necesidades y validar hipótesis."] },
    { id: 793, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿por qué es importante comparar los resultados de elicitación con fuentes independientes?", options: ["Para corroborar la veracidad de la información y descartar sesgos o errores individuales.", "Para duplicar el trabajo de documentación sin sentido.", "Para sancionar a los empleados que dieron información incorrecta.", "Para retrasar la entrega del proyecto."], correct: 0, explanation: "La validación cruzada asegura alta fidelidad en los requerimientos recopilados.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Comparación con fuentes independientes: Descartar sesgos y asegurar veracidad."] },
    { id: 794, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "According to BABOK v3 (Sec. 4.4), ¿qué se debe adaptar al comunicar información de análisis a distintas audiencias?", options: ["El nivel de detalle, el formato de presentación y el lenguaje técnico utilizado.", "Únicamente el horario en que se envía el correo electrónico.", "El tipo de moneda en que se cotiza el proyecto.", "La marca del software de videollamada."], correct: 0, explanation: "Adaptar el mensaje asegura que cada perfil (técnico o ejecutivo) comprenda el impacto.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Adaptación de comunicación: Nivel de detalle y lenguaje según la audiencia."] },
    { id: 795, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿qué estrategia fomenta la confianza en la colaboración con stakeholders?", options: ["Mantener la transparencia, cumplir los compromisos adquiridos y escuchar activamente sus perspectivas.", "Ocultar los problemas técnicos y prometer fechas imposibles.", "Imponer decisiones unilaterales sin derecho a discusión.", "Ignorar las retroalimentaciones negativas."], correct: 0, explanation: "La confianza se construye mediante la transparencia, el respeto y la escucha activa.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Fomento de confianza: Transparencia, cumplimiento y escucha activa."] },
    { id: 796, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿qué objetivo tiene preparar el material de apoyo antes de una sesión de elicitación?", options: ["Garantizar que la sesión sea productiva, fluida y mantenga el enfoque en los objetivos definidos.", "Imprimir miles de páginas para llenar el escritorio de los asistentes.", "Gastar el presupuesto asignado al proyecto.", "Demorar el inicio de las entrevistas."], correct: 0, explanation: "Un material bien preparado optimiza el tiempo de los expertos y del analista.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Material de apoyo en elicitación: Asegura sesiones productivas y enfocadas."] },
    { id: 797, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿qué comprende la elicitación colaborativa?", options: ["Interacción directa e intercambio activo de información entre el analista y las partes interesadas.", "Estudio solitario de manuales técnicos en una oficina cerrada.", "Ejecución automática de pruebas de software en servidores de nube.", "Auditoría de estados financieros contables."], correct: 0, explanation: "Involucra técnicas como entrevistas, talleres, grupos focales y tormentas de ideas.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2", summary: ["Elicitación colaborativa: Interacción directa e intercambio activo de ideas."] },
    { id: 798, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿qué ocurre cuando se detectan ambigüedades al confirmar la elicitación?", options: ["Se investiga y aclara con los participantes para evitar interpretaciones erróneas en el diseño.", "Se ignoran y se deja que el equipo de desarrollo adivine.", "Se cancela inmediatamente el proyecto comercial.", "Se despide al personal involucrado."], correct: 0, explanation: "Aclarar ambigüedades a tiempo previene costosos defectos en fases posteriores.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Gestión de ambigüedades: Aclarar a tiempo para prevenir defectos futuros."] },
    { id: 799, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿cuál es la ventaja de utilizar presentaciones visuales al comunicar información?", options: ["Facilitan la síntesis de conceptos complejos y mejoran la retención y entendimiento de la audiencia.", "Incrementan el número de errores tipográficos en los documentos.", "Confunden deliberadamente a los tomadores de decisiones.", "Reemplazan por completo los contratos legales firmados."], correct: 0, explanation: "Los elementos visuales agilizan la comprensión global de los escenarios comerciales.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Presentaciones visuales: Facilitan síntesis y mejoran el entendimiento global."] },
    { id: 800, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿cómo se gestionan los conflictos de intereses entre diferentes partes interesadas?", options: ["Mediante negociación, facilitación de acuerdos y búsqueda de soluciones orientadas al valor global de la empresa.", "Imponiendo la voluntad del empleado con menor jerarquía.", "Ocultando el conflicto hasta que estalle en producción.", "Dejando que el problema se resuelva solo por azar."], correct: 0, explanation: "La facilitación experta ayuda a conciliar posturas encontradas hacia un objetivo común.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Gestión de conflictos: Negociación y facilitación orientadas al valor empresarial."] },
    { id: 801, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿por qué es importante definir la agenda antes de una sesión de elicitación?", options: ["Para asegurar que todos los temas críticos sean cubiertos dentro del tiempo asignado.", "Para aburrir a los participantes con reglas estrictas.", "Para impedir que los asistentes realicen preguntas imprevistas.", "Para duplicar la duración de las reuniones."], correct: 0, explanation: "Una agenda estructurada guía el ritmo de la sesión y previene desviaciones de alcance.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Agenda de elicitación: Guía el ritmo y asegura cobertura de temas críticos."] },
    { id: 802, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "According to BABOK v3 (Sec. 4.2), ¿qué técnica de investigación se basa en el análisis de normativas y documentos existentes?", options: ["Análisis de documentos (Document Analysis).", "Pruebas de estrés de bases de datos relacionales.", "Entrevistas individuales abiertas informales.", "Creación de prototipos visuales en Figma."], correct: 0, explanation: "El análisis de documentos estudia manuales, políticas y contratos para extraer reglas de negocio.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2", summary: ["Análisis de documentos: Estudio sistemático de políticas y manuales existentes."] },
    { id: 803, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿qué implica la confirmación formal de los resultados de elicitación?", options: ["Obtener la aprobación explícita de las fuentes de información de que lo capturado es correcto.", "Firmar un contrato de compraventa de bienes raíces.", "Autorizar el presupuesto anual de marketing corporativo.", "Certificar las redes de telecomunicaciones."], correct: 0, explanation: "La confirmación formal mitiga el riesgo de malentendidos antes de modelar o diseñar.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Confirmación formal: Aprobación explícita de la exactitud de los datos recopilados."] },
    { id: 804, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿qué asegura la bidireccionalidad al comunicar información comercial?", options: ["Que la audiencia pueda realizar preguntas, aclarar dudas y confirmar su entendimiento mutuo.", "Que el analista hable sin parar durante horas sin permitir interrupciones.", "Que se envíen correos masivos automáticos sin respuesta posible.", "Que se eliminen las juntas presenciales por completo."], correct: 0, explanation: "La comunicación efectiva requiere retroalimentación bidireccional constante.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Comunicación bidireccional: Permite preguntas, aclaraciones y entendimiento mutuo."] },
    { id: 805, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿qué impacto tiene un entorno de colaboración positivo en el análisis de negocios?", options: ["Estimula la creatividad, acelera la resolución de problemas y mejora la calidad de los requerimientos.", "Incrementa la rotación de personal y la frustración general.", "Reduce la calidad del software en producción.", "Disminuye el compromiso del patrocinador."], correct: 0, explanation: "Un clima de confianza y apertura potencia el éxito de las iniciativas de cambio.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Clima de colaboración positivo: Estimula creatividad y mejora calidad de requisitos."] },
    { id: 806, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿cómo se preparan los participantes para una sesión de elicitación?", options: ["Proveyéndoles contexto previo, lecturas de apoyo y objetivos claros de lo que se discutirá.", "Exigiéndoles que resuelvan un examen sorpresa de matemáticas.", "Ocultándoles el propósito de la reunión hasta el último minuto.", "Pidiéndoles que traigan su propio equipo de cómputo y servidores."], correct: 0, explanation: "Los participantes preparados aportan información de mayor calidad durante las sesiones.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Preparación de participantes: Proveer contexto previo y objetivos claros."] },
    { id: 807, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿en qué consiste la observación como técnica de elicitación?", options: ["Estudiar cómo las partes interesadas realizan su trabajo en su entorno operativo real.", "Ver películas corporativas en una sala de cine.", "Instalar cámaras ocultas sin autorización en las oficinas.", "Revisar balances contables anuales en papel."], correct: 0, explanation: "La observación directa revela detalles operativos que los usuarios a veces omiten en entrevistas.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2", summary: ["Observación: Estudio directo del trabajo en el entorno operativo real."] },
    { id: 808, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿qué técnica se usa frecuentemente para confirmar resultados con grandes grupos?", options: ["Talleres de validación o revisión estructurada por pares y stakeholders clave.", "Enviar un mensaje cifrado sin remitente.", "Preguntar al azar en la calle a transeúntes.", "Realizar sorteos en rifas corporativas."], correct: 0, explanation: "Los talleres de revisión permiten validar alcances complejos de manera conjunta y rápida.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Talleres de validación: Revisión estructurada conjunta para grandes grupos."] },
    { id: 809, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿qué componente no debe faltar en un paquete formal de comunicación de análisis?", options: ["Resumen ejecutivo, alcance, supuestos, restricciones y detalles de los requerimientos.", "El menú de la cafetería de la oficina.", "La biografía personal de los desarrolladores.", "Las canciones favoritas del analista de negocios."], correct: 0, explanation: "Los paquetes formales deben estructurar claramente el contexto y los datos clave del análisis.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Paquete formal de comunicación: Resumen, alcance, supuestos y restricciones."] },
    { id: 810, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿por qué es necesario monitorear continuamente la colaboración de las partes interesadas?", options: ["Porque las actitudes y el nivel de compromiso pueden cambiar conforme evoluciona el proyecto.", "Porque el software deja de funcionar si no se vigila a los usuarios.", "Porque es un requisito legal de auditoría fiscal gubernamental.", "Porque reemplaza la necesidad de hacer pruebas de calidad."], correct: 0, explanation: "Monitorear la colaboración permite detectar fatiga, resistencia o pérdida de interés a tiempo.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Monitoreo de colaboración: Detectar cambios de actitud y compromiso a lo largo del tiempo."] },
    { id: 811, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿qué importancia tiene definir los límites y restricciones en la preparación de elicitación?", options: ["Evitar que las sesiones se desvíen hacia temas irrelevantes fuera del alcance de la iniciativa.", "Aumentar la duración de las juntas sin beneficio alguno.", "Garantizar que no se hable de tecnología bajo ninguna circunstancia.", "Impedir la participación de los expertos de negocio."], correct: 0, explanation: "Acotar los límites protege el tiempo y mantiene el foco en los objetivos de la sesión.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Límites en preparación: Evitar desviaciones de alcance y mantener el foco."] },
    { id: 812, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿qué ventaja aportan los 'Grupos Focales' (Focus Groups) en la elicitación?", options: ["Permiten capturar percepciones, opiniones y actitudes cualitativas de un grupo representativo de usuarios.", "Permiten escribir código fuente de manera automática en Java.", "Son útiles para calcular la nómina salarial corporativa.", "Reemplazan la necesidad de desplegar software en producción."], correct: 0, explanation: "Los grupos focales extraen retroalimentación cualitativa guiada por un moderador experto.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2", summary: ["Grupos focales: Captura de opiniones y actitudes cualitativas de usuarios representativos."] },
    { id: 813, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿cómo se procede si se descubre una contradicción crítica durante la confirmación de elicitación?", options: ["Se convoca a las partes interesadas involucradas para conciliar la diferencia y documentar el acuerdo resultante.", "Se borra toda la información recopilada sin avisar a nadie.", "Se elige una opción al azar sin consultar al negocio.", "Se cancela el contrato de todos los proveedores."], correct: 0, explanation: "Las contradicciones deben resolverse colaborativamente antes de avanzar al diseño.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Resolución de contradicciones: Sesiones de conciliación con stakeholders involucrados."] },
    { id: 814, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿qué beneficio aporta adaptar el vocabulario al comunicar información de análisis?", options: ["Evita malentendidos al utilizar términos familiares para la audiencia específica (negocio o técnica).", "Garantiza que nadie comprenda el mensaje transmitido.", "Obliga a la empresa a cambiar de idioma oficial.", "Incrementa los errores de sintaxis en el código de programación."], correct: 0, explanation: "Hablar el 'idioma' de la audiencia mejora notablemente la claridad y aceptación de las propuestas.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Adaptación de vocabulario: Usar términos familiares para evitar malentendidos."] },
    { id: 815, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿qué actitud debe mantener el analista de negocios al facilitar la colaboración?", options: ["Neutralidad, apertura mental, respeto y enfoque en la resolución objetiva de problemas.", "Actitud autoritaria e impositiva sin derecho a réplica.", "Indiferencia total ante las opiniones de los expertos.", "Desconfianza permanente hacia todo el personal."], correct: 0, explanation: "La neutralidad y el respeto fomentan un ambiente seguro para el intercambio de ideas.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Neutralidad del analista: Fomentar apertura y respeto en la facilitación."] },
    { id: 816, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.1), ¿qué recursos tecnológicos deben preverse en la logística de elicitación virtual?", options: ["Plataformas de videoconferencia estables, herramientas de pizarra colaborativa y micrófonos adecuados.", "Impresoras láser de alta velocidad para papel.", "Cables de red de fibra óptica submarina.", "Servidores físicos de centro de datos."], correct: 0, explanation: "La logística virtual exige asegurar herramientas digitales funcionales y buena conectividad.", pageRef: "BABOK v3, Cap. 4, Sec. 4.1", summary: ["Logística virtual: Asegurar plataformas de videoconferencia y pizarras colaborativas."] },
    { id: 817, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.2), ¿qué objetivo persigue la 'Tormenta de Ideas' (Brainstorming)?", options: ["Generar una gran cantidad de ideas y opciones creativas en un período corto de tiempo sin juzgarlas inicialmente.", "Escribir un manual contable de 500 páginas en silencio absoluto.", "Auditar las cuentas bancarias de la corporación.", "Instalar sistemas operativos en servidores."], correct: 0, explanation: "El brainstorming prioriza la cantidad y creatividad de ideas antes de filtrarlas.", pageRef: "BABOK v3, Cap. 4, Sec. 4.2", summary: ["Brainstorming: Generación masiva de ideas creativas sin juicio inicial."] },
    { id: 818, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.3), ¿por qué es fundamental registrar el rastro de las confirmaciones de elicitación?", options: ["Para mantener evidencia de qué stakeholder aprobó qué información y en qué fecha.", "Para complicar innecesariamente los archivos del proyecto.", "Para sancionar a los analistas en caso de errores de software.", "Para ocupar espacio de almacenamiento en el disco duro."], correct: 0, explanation: "El registro histórico protege contra cambios de opinión sin sustento y ambigüedades futuras.", pageRef: "BABOK v3, Cap. 4, Sec. 4.3", summary: ["Registro de confirmaciones: Evidencia histórica de aprobaciones y fechas."] },
    { id: 819, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.4), ¿qué rol juegan los canales informales en la comunicación del análisis?", options: ["Complementan los canales formales al permitir alineaciones rápidas y resolución ágil de dudas cotidianas.", "Reemplazan por completo la documentación oficial del proyecto.", "Están prohibidos estrictamente por las normas del BABOK.", "Sirven únicamente para difundir rumores corporativos."], correct: 0, explanation: "La comunicación informal agiliza la fluidez diaria, aunque los acuerdos clave deben formalizarse.", pageRef: "BABOK v3, Cap. 4, Sec. 4.4", summary: ["Canales informales: Complementan la comunicación y permiten alineaciones rápidas."] },
    { id: 820, chapter: 3, chapterTitle: "Cap. 3: Obtención y Colaboración", q: "Según el BABOK v3 (Sec. 4.5), ¿qué beneficio directo aporta una colaboración efectiva al ciclo de vida del proyecto?", options: ["Reduce drásticamente los retrabajos por requerimientos malentendidos y acelera la entrega de valor.", "Aumenta los costos operativos y duplica los tiempos de desarrollo.", "Elimina la necesidad de realizar pruebas de calidad de software.", "Genera conflictos permanentes entre negocio y tecnología."], correct: 0, explanation: "Colaborar eficazmente alinea las expectativas desde el inicio, evitando retrabajos costosos.", pageRef: "BABOK v3, Cap. 4, Sec. 4.5", summary: ["Beneficio de colaboración: Reduce retrabajos y acelera la entrega de valor."] },

    // --- CAPÍTULO 4: Gestión del Ciclo de Vida de los Requisitos (40 preguntas) ---
    { id: 821, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué beneficios aporta la 'Trazabilidad de Requisitos'?", options: ["Análisis de impacto más sencillo, descubrimiento confiable de lagunas y evaluación de la cobertura del cambio.", "Automatización completa de las pruebas de regresión visual.", "Eliminación de la necesidad de gestionar dependencias técnicas.", "Reducción automática de los costos de infraestructura."], correct: 0, explanation: "La trazabilidad vincula requerimientos y diseños para facilitar análisis de impacto y detectar lagunas de alcance.", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Trazabilidad: Linaje de requisitos, análisis de impacto y detección de lagunas."] },
    { id: 822, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿cuáles son los factores clave que influyen en la 'Priorización de Requisitos'?", options: ["Beneficio, penalización, costo, riesgo, dependencias, estabilidad, sensibilidad temporal y cumplimiento.", "Únicamente la fecha en que el cliente solicitó el requerimiento por correo.", "La cantidad de líneas de código necesarias para programar la funcionalidad.", "El orden alfabético de las épicas registradas en el backlog."], correct: 0, explanation: "La priorización pondera múltiples factores de negocio y técnicos como beneficio, penalización, costo, riesgo y dependencias.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3.1", summary: ["Priorización: Criterios multidimensionales (Beneficio, Costo, Riesgo, Dependencias)."] },
    { id: 823, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿cuál es el propósito de la tarea 'Mantener requisitos'?", options: ["Conservar la precisión y coherencia de los requisitos a lo largo del cambio y apoyar su reutilización.", "Borrar permanentemente todos los requerimientos al finalizar cada sprint.", "Incurrir en modificaciones de código sin control de versiones.", "Ocultar los cambios aprobados al equipo de desarrollo."], correct: 0, explanation: "Asegura que los requisitos permanezcan válidos, actualizados y disponibles para reutilización a largo plazo.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2.1", summary: ["Mantener requisitos: Garantizar precisión a lo largo del tiempo y reutilización."] },
    { id: 824, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿qué implica la tarea 'Evaluar cambios en los requisitos'?", options: ["Analizar las implicaciones e impactos de los cambios propuestos antes de decidir si se aprueban, modifican o deniegan.", "Aceptar automáticamente cualquier modificación solicitada por el cliente sin análisis.", "Cambiar el nombre del proyecto cada semana por motivos estéticos.", "Despedir al equipo si surge un defecto."], correct: 0, explanation: "Evalúa beneficios, costos, impactos y alineación estratégica de cualquier modificación propuesta.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4.1", summary: ["Evaluar cambios: Analizar impactos de valor, costos y riesgos de modificaciones."] },
    { id: 825, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿cuál es el objetivo de 'Aprobar requisitos'?", options: ["Obtener acuerdo y aprobación formal o informal de los requisitos y diseños para continuar el trabajo.", "Firmar contratos de compraventa de bienes raíces corporativos.", "Autorizar el presupuesto anual de marketing de la empresa.", "Certificar las redes de telecomunicaciones externas."], correct: 0, explanation: "Formaliza el acuerdo entre stakeholders de que la información es adecuada para avanzar.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5.1", summary: ["Aprobar requisitos: Obtener acuerdo y consenso para continuar el desarrollo."] },
    { id: 826, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué tipos de relaciones de trazabilidad define el estándar?", options: ["Derivar, Depende, Satisfacer y Validar.", "Padre, Hijo, Hermano y Primo.", "Inicio, Desarrollo, Pruebas y Cierre.", "Causa, Efecto, Solución y Falla."], correct: 0, explanation: "El BABOK define relaciones como Derivar (niveles de abstracción), Depende, Satisfacer y Validar (con pruebas).", pageRef: "BABOK v3, Cap. 5, Sec. 5.1.4", summary: ["Relaciones de trazabilidad: Derivar, Depende, Satisfacer y Validar."] },
    { id: 827, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué características hacen que un requisito sea un buen candidato para la 'Reutilización'?", options: ["Que describa obligaciones continuas, normas de calidad, reglas de negocio o servicios comunes aplicables a largo plazo.", "Que mencione el nombre de un empleado específico que ya renunció.", "Que esté escrito en un lenguaje de programación obsoleto.", "Que aplique únicamente para una pantalla temporal de prueba."], correct: 0, explanation: "Los requisitos reutilizables describen reglas, procesos o servicios útiles para múltiples iniciativas futuras.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2.4", summary: ["Reutilización de requisitos: Obligaciones continuas, reglas y servicios comunes."] },
    { id: 828, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿a qué se refiere el factor de priorización 'Penalización'?", options: ["Las consecuencias negativas o costos que resultan de no implementar un requisito dado (ej. incumplimiento normativo).", "Una multa económica impuesta directamente a los desarrolladores por cada error de código.", "La cantidad de horas extra obligatorias de trabajo nocturno.", "La pérdida de puntos en un videojuego corporativo."], correct: 0, explanation: "La penalización evalúa el impacto negativo de omitir un requerimiento regulatorio o de negocio crítico.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3.4", summary: ["Penalización en priorización: Consecuencias de no implementar un requisito."] },
    { id: 829, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿qué elementos abarca el 'Análisis de Impacto' ante un cambio propuesto?", options: ["Beneficio del cambio, costo total, número de clientes afectados, impacto en el cronograma y urgencia.", "El color del tema visual en la aplicación móvil.", "La marca del ordenador portátil de los analistas.", "El número de pisos del edificio corporativo."], correct: 0, explanation: "El análisis de impacto valora beneficio, costo de retrabajo, clientes afectados, plazos y urgencia.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4.4", summary: ["Análisis de impacto: Beneficio, costo, alcance, cronograma y urgencia."] },
    { id: 830, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "According to BABOK v3 (Sec. 5.5), ¿qué papel juega el 'Consenso' en el proceso de aprobación de requisitos?", options: ["Se busca el acuerdo general entre los stakeholders para mantener el apoyo, aunque no siempre se requiere unanimidad absoluta.", "Obliga a que el 100% de los empleados firmen físicamente un documento impreso.", "Significa que los desarrolladores tienen la autoridad de vetar cualquier decisión gerencial.", "No tiene ninguna importancia en la gestión ágil."], correct: 0, explanation: "Se busca consenso para alinear expectativas, gestionando los riesgos si existen desacuerdos.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5.4", summary: ["Consenso en aprobaciones: Buscar acuerdo general y gestionar riesgos de desacuerdo."] },
    { id: 831, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿por qué es importante mantener actualizado el repositorio de trazabilidad?", options: ["Para asegurar que cualquier cambio en un requisito de alto nivel refleje inmediatamente su impacto en diseños y pruebas.", "Para gastar más tiempo en tareas administrativas sin valor.", "Para impedir que los desarrolladores accedan al código fuente.", "Para duplicar el espacio de almacenamiento en el servidor."], correct: 0, explanation: "La trazabilidad actualizada previene desalineaciones entre la estrategia y la implementación técnica.", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Trazabilidad actualizada: Previene desalineaciones entre estrategia e implementación."] },
    { id: 832, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué se debe verificar al mantener un requisito para reutilización?", options: ["Que esté desvinculado de contextos obsoletos y sea modularmente independiente.", "Que contenga nombres de empleados que ya no trabajan en la empresa.", "Que esté escrito en un código binario incomprensible.", "Que no tenga ninguna documentación adjunta."], correct: 0, explanation: "Los requisitos reutilizables deben ser genéricos, claros y estar limpios de referencias obsoletas.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2", summary: ["Requisitos reutilizables: Deben ser modulares, claros y sin referencias obsoletas."] },
    { id: 833, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿qué mide el factor de priorización 'Costo'?", options: ["El esfuerzo financiero y de recursos necesarios para implementar un requisito o diseño.", "El costo de la cafetería de la oficina.", "El precio de venta del software al cliente final.", "El salario mensual del analista de negocios."], correct: 0, explanation: "El costo evalúa los recursos económicos y operativos requeridos para construir la capacidad.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3", summary: ["Factor costo en priorización: Esfuerzo financiero y de recursos necesarios."] },
    { id: 834, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿quiénes deben participar en la evaluación de cambios en los requisitos?", options: ["Los roles definidos en la gobernanza, incluyendo patrocinadores, analistas y expertos técnicos.", "Únicamente el personal de limpieza de la empresa.", "Los usuarios externos que no conocen el proyecto.", "Cualquier transeúnte de la calle."], correct: 0, explanation: "La evaluación de cambios requiere la participación de los tomadores de decisiones y evaluadores de impacto.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4", summary: ["Participación en cambios: Tomadores de decisiones y analistas definidos en la gobernanza."] },
    { id: 835, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿qué diferencia existe entre aprobación formal e informal?", options: ["La formal deja un registro legal o contractual vinculante; la informal se basa en acuerdos de palabra o correos de aceptación rápida.", "La formal es digital y la informal es escrita en papel.", "No existe ninguna diferencia en el estándar BABOK v3.", "La informal solo aplica para contratos internacionales de millones de dólares."], correct: 0, explanation: "La formalidad depende del nivel de riesgo y gobernanza requerida por la organización.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5", summary: ["Aprobación formal vs informal: Registro vinculante vs acuerdo ágil rápido."] },
    { id: 836, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué relación de trazabilidad vincula un requisito con su caso de prueba correspondiente?", options: ["La relación de validación (Validate).", "La relación de herencia familiar.", "La relación de costos financieros.", "La relación de sueldos y salarios."], correct: 0, explanation: "La relación 'Validar' conecta el requisito con los elementos de prueba que confirman su cumplimiento.", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Relación de validación: Conecta requisitos con sus pruebas de aceptación."] },
    { id: 837, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué riesgo se evita al mantener adecuadamente los requerimientos?", options: ["Utilizar información desactualizada que provoque retrabajos o fallas en el desarrollo.", "Aumentar la velocidad de entrega en los sprints ágiles de manera descontrolada.", "Reducir los costos de infraestructura de servidores físicos.", "Mejorar la satisfacción del cliente final."], correct: 0, explanation: "Mantener los requisitos previene el uso de especificaciones obsoletas en la codificación.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2", summary: ["Riesgo evitado al mantener requisitos: Uso de especificaciones obsoletas y retrabajo."] },
    { id: 838, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿qué evalúa el factor de priorización 'Sensibilidad Temporal' (Time Sensitivity)?", options: ["Si la urgencia o una fecha límite estricta del mercado afecta el valor de implementar el requisito a tiempo.", "La cantidad de horas que duermen los desarrolladores por la noche.", "La velocidad de conexión a internet de la red local de la oficina.", "El tiempo de duración de las reuniones ejecutivas."], correct: 0, explanation: "La sensibilidad temporal mide si el valor del requisito expira o decae si se entrega tarde.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3", summary: ["Sensibilidad temporal: Urgencia y valor condicionado a fechas límite del mercado."] },
    { id: 839, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿qué sucede si se aprueba un cambio sin realizar un análisis de impacto previo?", options: ["Se incrementa drásticamente el riesgo de desviar el presupuesto, el alcance y los plazos acordados.", "Se garantiza el éxito absoluto y temprano de la iniciativa comercial.", "Se reduce el costo de desarrollo a cero de manera automática.", "Se eliminan todos los defectos de software en producción."], correct: 0, explanation: "Omitir el análisis de impacto expone al proyecto a desviaciones descontroladas ('scope creep').", pageRef: "BABOK v3, Cap. 5, Sec. 5.4", summary: ["Omitir análisis de impacto: Expone al proyecto a desviaciones de alcance y presupuesto."] },
    { id: 840, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿qué se registra formalmente al aprobar un requisito?", options: ["La línea base de referencia, la fecha de aprobación y la identidad de los aprobadores autorizados.", "La lista de compras de supermercado de la oficina.", "Los códigos fuente de los microservicios backend.", "Las contraseñas de acceso al servidor de base de datos."], correct: 0, explanation: "Registrar la aprobación congela la línea base y establece responsabilidades claras de gobernanza.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5", summary: ["Registro de aprobación: Línea base congelada, fecha y nombres de aprobadores."] },
    { id: 841, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué permite identificar el análisis de cobertura mediante trazabilidad?", options: ["Requisitos huérfanos que no tienen justificación comercial o requerimientos sin pruebas asociadas.", "La cantidad de café consumida por los analistas durante el día.", "El color de la interfaz gráfica de usuario en Figma.", "La velocidad de escritura en el teclado del equipo."], correct: 0, explanation: "La cobertura muestra si todos los elementos están conectados y si existen elementos sin soporte.", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Análisis de cobertura por trazabilidad: Detecta requisitos huérfanos o sin pruebas."] },
    { id: 842, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué beneficios directos ofrece la reutilización de requisitos en múltiples proyectos?", options: ["Reducción de tiempos de análisis, estandarización corporativa y mayor calidad en reglas conocidas.", "Incremento de errores de sintaxis en el código fuente de los desarrolladores.", "Aumento de costos operativos y duplicación de documentación.", "Eliminación de la necesidad de interactuar con el cliente."], correct: 0, explanation: "Reutilizar artefactos probados agiliza el trabajo y asegura coherencia metodológica.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2", summary: ["Beneficios de reutilización: Menor tiempo de análisis y estandarización corporativa."] },
    { id: 843, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿cómo influyen las 'Dependencias' en la priorización de requisitos?", options: ["Un requisito prerrequisito debe implementarse antes que otro que dependa de él, sin importar su beneficio aislado.", "Permiten implementar cualquier funcionalidad en orden completamente aleatorio.", "Anulan la necesidad de evaluar el costo financiero del proyecto.", "Definen el diseño visual de los botones de la aplicación."], correct: 0, explanation: "Las dependencias técnicas o de negocio restringen el orden lógico en que se pueden priorizar las entregas.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3", summary: ["Dependencias en priorización: Restringen el orden lógico de implementación de entregables."] },
    { id: 844, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿qué opciones se pueden decidir tras evaluar una solicitud de cambio?", options: ["Aprobar, rechazar, modificar o aplazar la solicitud de cambio.", "Aceptar obligatoriamente el 100% de los cambios sin revisión.", "Borrar todo el historial de requerimientos del proyecto.", "Despedir al equipo técnico de desarrollo."], correct: 0, explanation: "La evaluación de cambios culmina en una decisión informada de aceptación, rechazo o diferimiento.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4", summary: ["Decisiones de cambio: Aprobar, rechazar, modificar o aplazar la solicitud."] },
    { id: 845, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿qué ocurre si un requisito aprobado sufre modificaciones posteriores?", options: ["Debe someterse nuevamente por el proceso formal de control de cambios y re-aprobación.", "Se actualiza en secreto sin que nadie se entere en el equipo.", "Se cancela inmediatamente el contrato comercial con el cliente.", "Se elimina del sistema de forma permanente."], correct: 0, explanation: "Cualquier modificación a una línea base aprobada requiere re-evaluación y nueva aprobación.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5", summary: ["Modificación a línea base: Requiere control de cambios y nueva aprobación formal."] },
    { id: 846, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué es una relación de tipo 'Derivar' (Derive) en la trazabilidad?", options: ["Cuando un requisito se desglosa o nace a partir de otro requisito de mayor nivel de abstracción.", "Cuando dos departamentos compiten por el presupuesto anual.", "Cuando un servidor se conecta a internet mediante red LAN.", "Cuando se imprimen copias físicas de un documento."], correct: 0, explanation: "La relación 'Derivar' conecta requerimientos de alto nivel (comerciales) con niveles más detallados (solución).", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Relación 'Derivar': Vincula requisitos generales con desgloses detallados."] },
    { id: 847, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué repositorio almacena los requisitos destinados a la reutilización corporativa?", options: ["Un repositorio centralizado o biblioteca de activos de procesos de la organización.", "Una carpeta temporal en el escritorio personal del analista junior.", "Un archivo de texto plano guardado en un correo electrónico borrado.", "Una libreta de notas impresa de papel."], correct: 0, explanation: "Los activos reutilizables se archivan en bibliotecas corporativas accesibles para futuras iniciativas.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2", summary: ["Repositorio de reutilización: Biblioteca centralizada de activos de procesos organizacionales."] },
    { id: 848, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿qué evalúa el factor 'Estabilidad' al priorizar un requisito?", options: ["La probabilidad de que el requisito cambie en el corto o mediano plazo.", "La resistencia física de los servidores de hardware ante sismos.", "El tiempo de contratación indefinida de los empleados.", "La velocidad de los procesadores de las computadoras."], correct: 0, explanation: "Un requisito inestable (sujeto a cambios constantes) puede devaluarse en su priorización inicial.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3", summary: ["Factor estabilidad en priorización: Probabilidad de modificaciones futuras en el requisito."] },
    { id: 849, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿qué rol cumple el analista de negocios al presentar un análisis de impacto de cambio?", options: ["Proveer información objetiva y detallada sobre costos, beneficios y riesgos para que los tomadores decidan.", "Imponer su propia decisión personal sin consultar a los patrocinadores.", "Ocultar la información financiera para acelerar el desarrollo.", "Programar el código fuente de la solución directamente."], correct: 0, explanation: "El BA facilita la decisión informada presentando con precisión los impactos del cambio.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4", summary: ["Rol del BA en impacto de cambios: Proveer datos objetivos para la toma de decisiones."] },
    { id: 850, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿qué significa alcanzar un acuerdo formal de aprobación?", options: ["Firmar o registrar la conformidad explícita de que la información de análisis es apta para continuar el diseño.", "Obligar a los empleados a trabajar horas extra nocturnas.", "Pagar una multa gubernamental por retrasos.", "Cambiar el nombre y logotipo de la empresa."], correct: 0, explanation: "El acuerdo formal valida que los entregables cumplen los estándares de calidad para avanzar.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5", summary: ["Acuerdo formal de aprobación: Validación de que los entregables son aptos para avanzar."] },
    { id: 851, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué facilita la matriz de trazabilidad ante auditorías regulatorias?", options: ["Demostrar claramente el linaje y cumplimiento de los requerimientos de cumplimiento desde su origen hasta las pruebas.", "Ocultar información confidencial a las autoridades gubernamentales.", "Eliminar por completo la necesidad de documentar procesos.", "Duplicar los costos operativos de la empresa."], correct: 0, explanation: "La trazabilidad ofrece evidencia transparente del cumplimiento normativo y de negocio.", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Trazabilidad en auditorías: Evidencia transparente del linaje y cumplimiento normativo."] },
    { id: 852, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué se debe hacer con los requisitos que pierden su vigencia comercial?", options: ["Desactivarlos o retirarlos formalmente del alcance para evitar confusiones en el equipo.", "Mantenerlos activos y programarlos en producción obligatoriamente.", "Ignorarlos y dejarlos mezclados con los requisitos vigentes.", "Duplicarlos en todos los repositorios de la empresa."], correct: 0, explanation: "Retirar requisitos obsoletos mantiene limpio el backlog y protege el enfoque del proyecto.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2", summary: ["Requisitos obsoletos: Retirarlos del alcance para mantener limpio el backlog."] },
    { id: 853, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿cómo se aplica el factor 'Cumplimiento' (Regulatory Compliance) en la priorización?", options: ["Los requisitos legales o normativos obligatorios suelen priorizarse al máximo para evitar sanciones legales graves.", "Se ignoran por completo si el cliente no los solicita expresamente.", "Se dejan al final de la lista de prioridades para el último sprint.", "Se reemplazan por contratos informales de palabra."], correct: 0, explanation: "El cumplimiento normativo es mandatorio y precede a características opcionales de negocio.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3", summary: ["Cumplimiento en priorización: Requisitos legales obligatorios con máxima prioridad."] },
    { id: 854, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "According to BABOK v3 (Sec. 5.4), ¿qué sucede con las tareas de diseño y desarrollo si un cambio es rechazado?", options: ["Continúan ejecutándose de acuerdo con la línea base aprobada original sin modificaciones.", "Se detiene la empresa entera de manera indefinida.", "Se modifica todo el código fuente de forma descontrolada.", "Se despide al equipo directivo."], correct: 0, explanation: "Rechazar un cambio protege la línea base vigente, permitiendo que el trabajo siga según lo planeado.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4", summary: ["Cambio rechazado: El proyecto continúa ejecutándose según la línea base aprobada original."] },
    { id: 855, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿por qué es importante registrar quién aprobó un requerimiento?", options: ["Para mantener la rendición de cuentas ('accountability') y saber a quién consultar ante futuros cambios.", "Para multar económicamente al aprobador si hay errores.", "Para impedir que los desarrolladores hablen con los gerentes.", "Para aumentar el tamaño de los documentos impresos."], correct: 0, explanation: "La rendición de cuentas asegura claridad en las responsabilidades de gobernanza.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5", summary: ["Rendición de cuentas en aprobación: Identificar responsables para futuros cambios."] },
    { id: 856, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.1), ¿qué relación indica que un requisito de diseño cumple con un requisito de usuario?", options: ["La relación de satisfacción (Satisfy).", "La relación de parentesco familiar.", "La relación de costos contables.", "La relación de sueldos y salarios."], correct: 0, explanation: "La relación 'Satisfacer' vincula un diseño o solución con el requerimiento al que da respuesta.", pageRef: "BABOK v3, Cap. 5, Sec. 5.1", summary: ["Relación 'Satisfacer': Vincula soluciones de diseño con requisitos de usuario."] },
    { id: 857, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.2), ¿qué ventaja ofrece mantener un control estricto de versiones en los requisitos?", options: ["Permite auditar el historial de cambios, saber quién modificó qué y revertir errores si es necesario.", "Oculta las modificaciones recientes al equipo técnico.", "Elimina la necesidad de utilizar repositorios digitales.", "Duplica los costos operativos de la empresa."], correct: 0, explanation: "El control de versiones garantiza transparencia y trazabilidad temporal de los artefactos.", pageRef: "BABOK v3, Cap. 5, Sec. 5.2", summary: ["Control de versiones: Permite auditar historial, cambios y revertir errores."] },
    { id: 858, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.3), ¿qué ocurre cuando múltiples stakeholders tienen prioridades contradictorias?", options: ["El analista facilita sesiones de negociación basadas en los objetivos estratégicos y el valor corporativo global.", "Se impone el capricho del stakeholder con voz más alta sin análisis.", "Se cancela el proyecto y se despide a todos los empleados.", "Se ignoran las prioridades de todos por igual."], correct: 0, explanation: "La facilitación experta alinea las prioridades divergentes hacia la meta comercial de mayor valor.", pageRef: "BABOK v3, Cap. 5, Sec. 5.3", summary: ["Prioridades contradictorias: Negociación facilitada basada en valor estratégico global."] },
    { id: 859, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.4), ¿qué debe documentarse obligatoriamente en cada solicitud de cambio?", options: ["El motivo del cambio, el impacto estimado en costo/tiempo y los beneficios esperados.", "La marca del ordenador portátil del solicitante.", "El color favorito del equipo de desarrollo.", "Las canciones preferidas del analista de negocios."], correct: 0, explanation: "Documentar el impacto y la justificación asegura decisiones de gobernanza fundamentadas.", pageRef: "BABOK v3, Cap. 5, Sec. 5.4", summary: ["Documentación de solicitudes de cambio: Motivo, impacto estimado y beneficios esperados."] },
    { id: 860, chapter: 4, chapterTitle: "Cap. 4: Gestión del Ciclo de Vida", q: "Según el BABOK v3 (Sec. 5.5), ¿qué beneficio aporta obtener la aprobación formal de los requisitos clave?", options: ["Mitigar el riesgo de ambigüedades, alinear expectativas y comprometer formalmente a los patrocinadores.", "Garantizar que el software nunca tenga ningún tipo de defecto.", "Eliminar la necesidad de realizar pruebas de calidad.", "Reducir el presupuesto de la empresa a cero."], correct: 0, explanation: "La aprobación formal sella el compromiso y previene malentendidos futuros de alcance.", pageRef: "BABOK v3, Cap. 5, Sec. 5.5", summary: ["Beneficio de aprobación formal: Mitigar ambigüedades y comprometer a patrocinadores."] },

    // --- CAPÍTULO 5: Análisis de Estrategia (40 preguntas) ---
    { id: 861, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué son los objetivos SMART al definir el estado futuro?", options: ["Específicos, mensurables, factibles, relevantes y acotados en el tiempo.", "Simples, masivos, ágiles, rápidos y técnicos.", "Seguros, monetarios, automatizados, rigurosos y trazables.", "Sistemáticos, manuales, analíticos, repetibles y normativos."], correct: 0, explanation: "Criterio SMART: Specific, Measurable, Achievable, Relevant, Time-bound.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2.4", summary: ["Objetivos SMART: Específicos, medibles, factibles, relevantes y temporales."] },
    { id: 862, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿cuál es el propósito de 'Analizar el estado actual'?", options: ["Comprender las razones por las que una empresa necesita cambiar y qué se vería afectado por el cambio.", "Diseñar los planos arquitectónicos de las nuevas oficinas ejecutivas.", "Calcular la nómina neta de los empleados del próximo mes.", "Instalar actualizaciones del sistema operativo en las PCs."], correct: 0, explanation: "Establece la línea base y el contexto examinando procesos, tecnologías, cultura y necesidades de negocio.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1.1", summary: ["Analizar estado actual: Comprender el 'por qué' y establecer la línea base de la empresa."] },
    { id: 863, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿qué busca la tarea 'Evaluar riesgos' en el análisis de estrategia?", options: ["Comprender las consecuencias indeseables de fuerzas internas y externas durante la transición al estado futuro.", "Calcular el impuesto sobre la renta corporativo anual.", "Eliminar por completo cualquier tipo de incertidumbre en el universo comercial.", "Imponer sanciones disciplinarias al personal."], correct: 0, explanation: "Analiza probabilidad, impacto y consecuencias indeseables para recomendar cursos de acción.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3.1", summary: ["Evaluar riesgos: Analizar incertidumbres e impactos para recomendar acciones."] },
    { id: 864, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "According to BABOK v3 (Sec. 6.4), ¿cuál es el objetivo de 'Definir estrategia de cambio'?", options: ["Desarrollar y evaluar enfoques alternativos para el cambio y luego seleccionar el enfoque recomendado.", "Imponer una única solución técnica sin consultar a las partes interesadas.", "Reducir la plantilla de trabajadores en un 50% de manera arbitraria.", "Cambiar la misión de la empresa cada semana."], correct: 0, explanation: "Compara alternativas de cambio, analiza brechas y recomienda la estrategia de mayor valor.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4.1", summary: ["Definir estrategia de cambio: Evaluar alternativas y seleccionar el enfoque óptimo."] },
    { id: 865, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿de qué formas se pueden identificar las 'Necesidades Comerciales' (Business Needs)?", options: ["De arriba hacia abajo (objetivos estratégicos), de abajo hacia arriba (problemas operativos) o por impulsores externos.", "Únicamente mediante la intuición personal del director general sin datos.", "Exclusivamente por exigencia de los proveedores de café.", "Mediante sorteos aleatorios."], correct: 0, explanation: "Las necesidades surgen de forma top-down (estrategia), bottom-up (problemas operativos) o por controladores externos.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1.4", summary: ["Necesidades comerciales: Top-down, bottom-up o impulsores externos."] },
    { id: 866, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué componentes abarca el 'Alcance del Espacio de Solución'?", options: ["La gama de opciones a considerar (procesos, tecnología, estructura, políticas, productos) para cumplir objetivos.", "Únicamente la compra de licencias de software comercial de marca cerrada.", "El número exacto de líneas de código fuente que tendrá la aplicación.", "El presupuesto destinado a la fiesta de fin de año de la empresa."], correct: 0, explanation: "Define qué tipos de opciones se evaluarán para resolver la necesidad del negocio.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2.4", summary: ["Alcance del espacio de solución: Opciones organizacionales, de procesos y tecnológicas."] },
    { id: 867, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿cómo se clasifican las actitudes hacia el riesgo según la tolerancia organizacional?", options: ["Aversión al riesgo, neutralidad y amor al riesgo (propensión).", "Optimista, pesimista y realista.", "Rápido, lento y moderado.", "Nacional, internacional y global."], correct: 0, explanation: "El BABOK describe la tolerancia al riesgo en aversión, neutralidad o aceptación/amor al riesgo.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3.4", summary: ["Tolerancia al riesgo: Aversión, neutralidad y propensión al riesgo."] },
    { id: 868, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿en qué consiste el 'Análisis de Brechas' (Gap Analysis)?", options: ["Identificar la diferencia entre las capacidades del estado actual y las requeridas en el estado futuro.", "Medir el espacio físico en metros cuadrados entre escritorios de oficina.", "Calcular la brecha salarial entre géneros en la industria tecnológica.", "Determinar el tiempo libre entre reuniones corporativas."], correct: 0, explanation: "Compara estado actual y futuro para identificar capacidades faltantes o mejoras necesarias.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4.4", summary: ["Análisis de brechas: Diferencia entre capacidades actuales y futuras."] },
    { id: 869, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿cómo se define el 'Valor Potencial' de un estado futuro?", options: ["El beneficio neto de la solución después de contabilizar los costos operativos e inversión necesaria.", "La cantidad de dinero gastada en publicidad en redes sociales.", "El número total de documentos PDF generados por el sistema.", "La cantidad de servidores físicos instalados en el centro de datos."], correct: 0, explanation: "Representa el beneficio neto estimado tras restar los costos operativos e inversión frente a no hacer nada.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2.4", summary: ["Valor potencial: Beneficio neto estimado tras deducir costos e inversión."] },
    { id: 870, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué son los 'Estados de Transición' en una estrategia de cambio?", options: ["Estados intermedios por los que la empresa debe operar cuando el estado futuro se logra gradualmente en el tiempo.", "Fases vacacionales obligatorias para el personal durante los despliegues.", "Cambios temporales en la moneda de curso legal del país.", "Interrupciones repentinas de energía eléctrica en los servidores."], correct: 0, explanation: "Son estados operativos intermedios necesarios cuando la entrega del estado futuro es escalonada.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4.4", summary: ["Estados de transición: Fases intermedias operativas durante la entrega gradual."] },
    { id: 871, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿qué elementos se analizan al estudiar la infraestructura en el estado actual?", options: ["Hardware, software, redes, instalaciones físicas y herramientas tecnológicas empleadas por la empresa.", "El color de las paredes de la oficina ejecutiva.", "La marca de los automóviles de los directivos.", "Las recetas de la cafetería corporativa."], correct: 0, explanation: "La infraestructura abarca los activos tecnológicos y físicos que soportan la operación presente.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Infraestructura en estado actual: Hardware, software, redes e instalaciones físicas."] },
    { id: 872, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué función cumplen los supuestos (assumptions) al definir el estado futuro?", options: ["Establecer condiciones consideradas verdaderas para efectos de planificación, aunque exista incertidumbre.", "Garantizar que el 100% de los pronósticos financieros se cumplan sin error.", "Eliminar por completo los riesgos del proyecto.", "Reemplazar los contratos legales firmados con proveedores."], correct: 0, explanation: "Los supuestos guían la planificación bajo premisas establecidas que deben ser validadas.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Supuestos en estado futuro: Condiciones asumidas verdaderas para la planificación."] },
    { id: 873, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿cómo se evalúa el 'Impacto' de un riesgo identificado?", options: ["La magnitud del daño o la pérdida de valor que sufriría la organización si el riesgo llegara a materializarse.", "El costo de las licencias de software comercial.", "El número de empleados que trabajan en la sucursal principal.", "La velocidad de conexión a internet de la red."], correct: 0, explanation: "El impacto mide cuán grave sería la consecuencia del riesgo sobre los objetivos de negocio.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Impacto de riesgo: Magnitud del daño o pérdida de valor sobre la organización."] },
    { id: 874, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué factores se consideran al comparar estrategias de cambio alternativas?", options: ["Costo total, valor esperado, riesgos asociados, plazos de entrega y alineación cultural.", "Únicamente el color del logotipo de la propuesta tecnológica.", "La nacionalidad de los programadores externos.", "El número de páginas del contrato comercial."], correct: 0, explanation: "Comparar alternativas requiere ponderar beneficios frente a costos, riesgos y viabilidad cultural.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Comparación de estrategias: Ponderación de costos, valor, riesgos y viabilidad."] },
    { id: 875, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿qué importancia tiene analizar la 'Cultura Organizacional' en el estado actual?", options: ["Permite entender cómo la empresa adopta el cambio y prever resistencias culturales profundas.", "Sirve para elegir la marca de computadoras portátiles de la oficina.", "Calcula automáticamente la declaración fiscal de impuestos.", "Define la velocidad de los servidores web."], correct: 0, explanation: "La cultura influye directamente en la disposición al cambio y en la efectividad de las soluciones.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Cultura organizacional: Clave para prever resistencias y adopción de cambios."] },
    { id: 876, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué son las limitaciones (constraints) al definir el estado futuro?", options: ["Restricciones o condiciones inquebrantables que limitan las opciones de diseño o ejecución de la solución.", "Sugerencias opcionales que el equipo puede ignorar libremente.", "Premios de productividad otorgados a los mejores empleados.", "Presupuestos ilimitados para gastos generales."], correct: 0, explanation: "Las limitaciones son fronteras estrictas (presupuesto, normativa, plazos) que no se pueden cruzar.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Limitaciones (constraints): Fronteras estrictas que restringen el espacio de solución."] },
    { id: 877, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿qué significa 'Mitigar' un riesgo en la estrategia corporativa?", options: ["Tomar acciones preventivas para reducir la probabilidad de ocurrencia o el impacto del riesgo.", "Ignorar el riesgo por completo y esperar a que ocurra el desastre.", "Duplicar el presupuesto operativo del proyecto sin justificación.", "Despedir a todo el personal de la empresa."], correct: 0, explanation: "La mitigación busca disminuir la exposición a la incertidumbre mediante controles adecuados.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Mitigación de riesgos: Acciones preventivas para reducir probabilidad e impacto."] },
    { id: 878, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué rol cumple el análisis de riesgos al definir la estrategia de cambio?", options: ["Ayuda a descartar estrategias excesivamente riesgosas o a planificar planes de contingencia adecuados.", "Garantiza que el proyecto no tenga ningún contratiempo nunca.", "Obliga a la empresa a gastar el doble de dinero en seguros.", "Elimina la necesidad de realizar pruebas de calidad de software."], correct: 0, explanation: "Conocer los riesgos de cada estrategia permite elegir la opción más segura y rentable.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Riesgos en estrategia: Permite descartar opciones peligrosas y planificar contingencias."] },
    { id: 879, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿qué abarca el análisis de la complejidad de los procesos en el estado actual?", options: ["Identificar cuellos de botella, redundancias, pasos manuales excesivos y demoras operativas.", "Medir el espacio físico en metros cuadrados de las oficinas.", "Calcular el salario neto de los gerentes corporativos.", "Definir los colores de la interfaz gráfica de usuario."], correct: 0, explanation: "Estudiar los procesos actuales revela ineficiencias que justifican la necesidad de cambio.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Complejidad de procesos actuales: Identifica cuellos de botella e ineficiencias operativas."] },
    { id: 880, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿por qué es crítico que los objetivos del estado futuro estén alineados con la misión corporativa?", options: ["Para asegurar que la iniciativa contribuya directamente a la visión y estrategia global de la empresa.", "Para cumplir un requisito burocrático sin importancia.", "Para duplicar el número de empleados en el departamento de sistemas.", "Para cambiar de nombre comercial cada semana."], correct: 0, explanation: "La alineación estratégica garantiza que los recursos se inviertan en proyectos que importan a la corporación.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Alineación estratégica: Asegura contribución directa a la misión y visión corporativa."] },
    { id: 881, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿qué representa la 'Probabilidad' de ocurrencia en la evaluación de riesgos?", options: ["La estimación de qué tan factible o frecuente es que un evento de riesgo se materialice.", "El costo monetario exacto de la infraestructura tecnológica.", "El número de líneas de código fuente en un repositorio Git.", "La cantidad de tazas de café consumidas al mes."], correct: 0, explanation: "La probabilidad mide la frecuencia esperada o la posibilidad estadística de que ocurra el riesgo.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Probabilidad de riesgo: Estimación de la factibilidad o frecuencia de materialización."] },
    { id: 882, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué se analiza al evaluar la 'Viabilidad' (Feasibility) de una estrategia de cambio?", options: ["Si la organización cuenta con los recursos, la tecnología, el presupuesto y las capacidades para ejecutarla con éxito.", "Si el logotipo de la empresa tiene los colores estéticos correctos.", "Si el edificio corporativo tiene suficientes pisos de altura.", "Si los empleados prefieren café o té por la mañana."], correct: 0, explanation: "La viabilidad comprueba si la estrategia es realizable de manera práctica en el mundo real.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Viabilidad de estrategia: Comprobación de recursos, tecnología y capacidades reales."] },
    { id: 883, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿qué fuentes de información se utilizan para analizar el estado actual?", options: ["Documentación existente, entrevistas a expertos, datos históricos de rendimiento y observación directa.", "Opiniones subjetivas al azar sin consultar a nadie.", "Lectura de horóscopos corporativos.", "Sorteos aleatorios en internet."], correct: 0, explanation: "El análisis del estado actual se fundamenta en evidencia empírica y documentación formal.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Fuentes para estado actual: Documentación, entrevistas, datos históricos y observación."] },
    { id: 884, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué beneficio aporta definir un estado futuro claro y desglosado?", options: ["Proporciona una dirección inequívoca y criterios objetivos para medir el éxito de la solución implementada.", "Aumenta la confusión de los desarrolladores y retrasa el proyecto.", "Elimina la necesidad de realizar pruebas de software.", "Duplica los costos operativos de la empresa."], correct: 0, explanation: "Un estado futuro bien definido actúa como brújula para evaluar el valor final obtenido.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Beneficio de estado futuro claro: Dirección inequívoca y criterios objetivos de éxito."] },
    { id: 885, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿qué estrategia se adopta cuando se decide 'Transferir' un riesgo?", options: ["Trasladar el impacto financiero o la responsabilidad a un tercero (ej. mediante pólizas de seguros o subcontratación).", "Asumir todo el daño sin protección alguna.", "Eliminar por completo la actividad comercial de la empresa.", "Ocultar la existencia del riesgo al consejo de administración."], correct: 0, explanation: "Transferir el riesgo externaliza las consecuencias negativas a terceras partes especializadas.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Transferir riesgo: Externalizar consecuencias a terceros mediante seguros o contratos."] },
    { id: 886, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué implica la transición gradual en una estrategia de cambio?", options: ["Implementar la solución en fases o estados intermedios para minimizar impactos operativos abruptos.", "Desplegar todo el sistema de golpe en producción un viernes por la noche sin pruebas.", "Cancelar el proyecto en la primera semana de ejecución.", "Cambiar la estructura directiva de la empresa diariamente."], correct: 0, explanation: "Las transiciones graduales aseguran continuidad operativa mientras se adopta el cambio.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Transición gradual: Implementación en fases para minimizar impactos operativos abruptos."] },
    { id: 887, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿cómo impacta la obsolescencia tecnológica en el análisis del estado actual?", options: ["Genera altos costos de mantenimiento, vulnerabilidades de seguridad e ineficiencias que motivan el cambio.", "Mejora automáticamente el rendimiento de los sistemas antiguos.", "Reduce los gastos operativos a cero de forma milagrosa.", "Garantiza el éxito financiero de la compañía."], correct: 0, explanation: "La tecnología obsoleta es uno de los impulsores operativos más comunes para iniciar transformaciones.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Obsolescencia tecnológica: Genera costos y vulnerabilidades que impulsan el cambio."] },
    { id: 888, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué son los indicadores clave de rendimiento (KPIs) en la definición del estado futuro?", options: ["Métricas cuantitativas utilizadas para evaluar si se están alcanzando los objetivos estratégicos establecidos.", "Opiniones subjetivas sin fundamento de los empleados junior.", "El número de correos electrónicos enviados al día.", "El color de la interfaz gráfica de la aplicación."], correct: 0, explanation: "Los KPIs permiten medir de manera objetiva el éxito y el valor real entregado por la solución.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["KPIs en estado futuro: Métricas cuantitativas para evaluar el logro de objetivos."] },
    { id: 889, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "According to BABOK v3 (Sec. 6.3), ¿qué significa 'Aceptar' un riesgo en la planificación estratégica?", options: ["Reconocer la existencia del riesgo pero decidir no tomar acciones preventivas debido a su bajo impacto o costo de mitigación.", "Ignorar la ley y cometer fraudes fiscales corporativos.", "Cerrar la empresa inmediatamente ante cualquier amenaza menor.", "Despedir a todos los gerentes de la compañía."], correct: 0, explanation: "Aceptar un riesgo implica asumir sus consecuencias si llega a ocurrir, por ser antieconómico mitigarlo.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Aceptar riesgo: Reconocer la amenaza sin mitigación previa por bajo impacto o costo."] },
    { id: 890, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué rol desempeña el análisis de brechas (gap analysis) al diseñar la estrategia?", options: ["Identificar con precisión qué capacidades, recursos o procesos faltan para pasar del estado actual al futuro.", "Medir el espacio físico en metros cuadrados de los escritorios de oficina.", "Calcular la brecha salarial de género en la industria.", "Determinar el horario de almuerzo de los empleados."], correct: 0, explanation: "El análisis de brechas expone exactamente el vacío que la nueva estrategia debe resolver.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Gap analysis en estrategia: Identifica capacidades y recursos faltantes para el estado futuro."] },
    { id: 891, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿por qué es necesario documentar las fortalezas del estado actual?", options: ["Para preservar capacidades valiosas y evitar destruirlas accidentalmente durante el proceso de cambio.", "Para despedir al personal asociado a dichas fortalezas.", "Para duplicar el presupuesto de marketing corporativo.", "Para eliminar por completo la fase de pruebas de software."], correct: 0, explanation: "Identificar fortalezas protege los activos operativos exitosos que deben mantenerse.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Fortalezas del estado actual: Preservar capacidades valiosas y evitar destruirlas."] },
    { id: 892, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué se entiende por 'Alcance del Estado Futuro'?", options: ["Los límites y fronteras de lo que la solución logrará una vez implementada con éxito.", "El presupuesto ilimitado de gastos generales de la empresa.", "El número exacto de líneas de código fuente del sistema.", "La ubicación geográfica de los servidores físicos en la nube."], correct: 0, explanation: "Define claramente qué se incluye y qué se excluye dentro de la visión del estado futuro.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Alcance del estado futuro: Límites y fronteras de lo que la solución logrará."] },
    { id: 893, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿qué es un plan de contingencia en la gestión de riesgos estratégicos?", options: ["Un curso de acción alternativo predefinido que se activará si el riesgo evaluado llega a materializarse.", "Una orden de despido masivo para el personal técnico.", "Un contrato legal de compraventa de bienes raíces.", "Una estrategia de marketing para redes sociales."], correct: 0, explanation: "El plan de contingencia prepara a la organización para responder rápidamente ante emergencias.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Plan de contingencia: Curso de acción alternativo ante la materialización de un riesgo."] },
    { id: 894, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué impacto tiene la cultura corporativa en la elección de la estrategia de cambio?", options: ["Estrategias que van en contra de los valores culturales establecidos enfrentarán una fuerte resistencia y posible fracaso.", "No tiene ninguna influencia en los proyectos tecnológicos.", "Obliga a la empresa a cambiar de idioma oficial obligatoriamente.", "Duplica la velocidad de desarrollo del software en producción."], correct: 0, explanation: "Ignorar la cultura organizacional al definir una estrategia de cambio incrementa drásticamente el riesgo de rechazo.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Cultura en estrategia: Ignorarla genera fuerte resistencia y riesgo de fracaso."] },
    { id: 895, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿qué evalúa el análisis de los flujos de información en el estado actual?", options: ["Cómo se genera, procesa, comparte y almacena la información crítica entre los diferentes departamentos.", "El diseño estético de las páginas web de entretenimiento externo.", "La velocidad de descarga de archivos personales de los empleados.", "La marca de los teléfonos celulares corporativos."], correct: 0, explanation: "Estudiar los flujos de datos actuales detecta silos de información e ineficiencias de comunicación.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Flujos de información actual: Detecta silos de datos e ineficiencias de comunicación."] },
    { id: 896, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿quiénes participan en la definición y validación del estado futuro?", options: ["Los patrocinadores, la alta dirección y las partes interesadas clave del negocio.", "Exclusivamente los desarrolladores junior de software.", "El personal de soporte técnico de nivel 1.", "Cualquier transeúnte externo sin relación con la empresa."], correct: 0, explanation: "Validar el estado futuro con los líderes asegura que la visión responda a las metas estratégicas.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Validación de estado futuro: Patrocinadores y alta dirección aseguran visión estratégica."] },
    { id: 897, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.3), ¿qué rol cumple el monitoreo continuo de riesgos durante la ejecución?", options: ["Detectar cambios en la probabilidad o impacto de los riesgos y activar controles preventivos a tiempo.", "Ocultar los problemas técnicos al consejo de administración.", "Duplicar los costos operativos del proyecto de forma injustificada.", "Eliminar por completo la necesidad de hacer pruebas."], correct: 0, explanation: "El entorno evoluciona, por lo que vigilar los riesgos previene sorpresas catastróficas.", pageRef: "BABOK v3, Cap. 6, Sec. 6.3", summary: ["Monitoreo de riesgos: Detectar cambios de probabilidad y activar controles a tiempo."] },
    { id: 898, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.4), ¿qué significa seleccionar una estrategia de cambio basada en 'Bajo Costo'?", options: ["Priorizar opciones que minimicen la inversión inicial, aunque puedan requerir mayores ajustes operativos futuros.", "Comprar el software más caro y complejo del mercado internacional.", "Contratar al mayor número posible de consultores externos costosos.", "Omitir el análisis técnico por completo."], correct: 0, explanation: "Las estrategias de bajo costo buscan eficiencia financiera inmediata con compensaciones operativas.", pageRef: "BABOK v3, Cap. 6, Sec. 6.4", summary: ["Estrategia de bajo costo: Minimizar inversión inicial con compensaciones operativas."] },
    { id: 899, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.1), ¿por qué se dice que el estado actual es la 'línea base' (baseline)?", options: ["Porque sirve como punto de referencia empírica para medir el impacto y la mejora de las soluciones futuras.", "Porque es un documento financiero que no puede modificarse nunca.", "Porque representa el estado final ideal de la corporación.", "Porque es un código de programación ejecutable."], correct: 0, explanation: "Sin conocer el punto de partida (línea base), es imposible calcular el valor o la mejora obtenida.", pageRef: "BABOK v3, Cap. 6, Sec. 6.1", summary: ["Estado actual como línea base: Punto de referencia empírica para medir futuras mejoras."] },
    { id: 900, chapter: 5, chapterTitle: "Cap. 5: Análisis de Estrategia", q: "Según el BABOK v3 (Sec. 6.2), ¿qué impacto tiene definir un estado futuro ambicioso pero inalcanzable?", options: ["Genera frustración, pérdida de credibilidad y desmotivación en los equipos de trabajo.", "Garantiza el éxito financiero absoluto y temprano de la empresa.", "Aumenta la velocidad de desarrollo del software milagrosamente.", "Reduce los costos operativos a cero."], correct: 0, explanation: "Los objetivos deben ser SMART (factibles), de lo contrario destruyen la moral y el compromiso.", pageRef: "BABOK v3, Cap. 6, Sec. 6.2", summary: ["Objetivos inalcanzables: Generan frustración, pérdida de credibilidad y desmotivación."] },

    // --- CAPÍTULO 6: Análisis de Requerimientos y Definición de Diseño - RADD (40 preguntas) ---
    { id: 901, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 2.5), ¿cuál es la distinción fundamental entre un Requisito y un Diseño?", options: ["Los requisitos se centran en la necesidad; los diseños se centran en la solución.", "Los requisitos son elaborados exclusivamente por arquitectos de software y los diseños por gerentes.", "Los requisitos solo se usan en metodologías tradicionales y los diseños en marcos ágiles.", "No existe diferencia conceptual; ambos términos son estrictamente sinónimos."], correct: 0, explanation: "El requisito aborda el 'qué' (la necesidad) mientras que el diseño aborda el 'cómo' (la representación utilizable de la solución).", pageRef: "BABOK v3, Cap. 2, Sec. 2.5", summary: ["Requisito (Necesidad) vs Diseño (Solución)."] },
    { id: 902, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué caracteriza a un requisito verificado como 'atómico'?", options: ["Que es autónomo y capaz de entenderse independientemente de otros requisitos o diseños.", "Que contiene mil páginas de especificación técnica detallada.", "Que está escrito utilizando fórmulas matemáticas de física cuántica.", "Que no puede ser modificado bajo ninguna circunstancia."], correct: 0, explanation: "La atomicidad implica que el requerimiento es autocontenido y comprensible por sí mismo.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2.1", summary: ["Requisito atómico: Autocontenido y comprensible de forma independiente."] },
    { id: 903, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿cuál es el propósito de la tarea 'Especificar y modelar requisitos'?", options: ["Analizar, sintetizar y refinar los resultados obtenidos convirtiéndolos en requisitos y diseños estructurados.", "Imprimir copias físicas de los documentos de texto para archivo.", "Traducir código de programación a lenguaje natural en papel.", "Formatear discos duros de computadoras."], correct: 0, explanation: "Transforma los hallazgos de elicitación en representaciones analíticas y modelos formales o informales.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1.1", summary: ["Especificar y modelar: Analizar y estructurar hallazgos en requisitos y diseños."] },
    { id: 904, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué evalúa la tarea 'Verificar requisitos'?", options: ["Que los requisitos y especificaciones de diseño cumplan con los estándares de calidad y sean utilizables.", "Que el software funcione sin ningún tipo de error en servidores de prueba.", "Que los clientes tengan la capacidad financiera para pagar el proyecto.", "Que el personal tenga contratos laborales indefinidos."], correct: 0, explanation: "La verificación comprueba la calidad intrínseca del documento/modelo (atómico, completo, claro, verificable).", pageRef: "BABOK v3, Cap. 7, Sec. 7.2.1", summary: ["Verificar requisitos: Comprobar calidad de escritura, claridad y cumplimiento de estándares."] },
    { id: 905, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.3), ¿qué busca la tarea 'Validar requisitos'?", options: ["Garantizar que un conjunto de requisitos o diseños proporcione valor comercial y respalde las metas de la organización.", "Comprobar que no existan errores de sintaxis en el código fuente de Java.", "Verificar que el servidor web soporte picos de tráfico en Navidad.", "Asegurar que los colores de la interfaz cumplan con normativas de contraste visual."], correct: 0, explanation: "La validación asegura que lo construido entregará el valor esperado y resolverá la necesidad del negocio.", pageRef: "BABOK v3, Cap. 7, Sec. 7.3.1", summary: ["Validar requisitos: Asegurar que el requisito entrega valor y cumple metas comerciales."] },
    { id: 906, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.4), ¿qué define la 'Arquitectura de Requisitos'?", options: ["La estructura de todos los requisitos y diseños para que funcionen de manera efectiva como un todo cohesivo.", "El plano físico de la construcción de concreto del edificio de oficinas.", "La red de fibra óptica submarina que conecta continentes.", "La jerarquía de directores ejecutivos en el organigrama."], correct: 0, explanation: "Estructura y conecta los requisitos y diseños para asegurar coherencia sistémica global.", pageRef: "BABOK v3, Cap. 7, Sec. 7.4", summary: ["Arquitectura de requisitos: Estructura cohesiva de requerimientos y diseños."] },
    { id: 907, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.5), ¿qué objetivo tiene 'Definir opciones de solución'?", options: ["Identificar, explorar y describir diferentes formas posibles de satisfacer la necesidad del negocio.", "Comprar el software más caro disponible en el mercado internacional.", "Contratar al mayor número posible de desarrolladores junior.", "Omitir el análisis técnico y programar directamente."], correct: 0, explanation: "Explora múltiples alternativas de solución (internas, externas, personalizadas o empaquetadas).", pageRef: "BABOK v3, Cap. 7, Sec. 7.5.1", summary: ["Definir opciones de solución: Explorar alternativas para satisfacer la necesidad."] },
    { id: 908, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.6), ¿en qué consiste 'Analizar valor potencial y recomendar solución'?", options: ["Evaluar el valor comercial de cada opción, comparar compensaciones y recomendar la de mayor valor global.", "Elegir siempre la opción más económica sin importar si resuelve el problema.", "Seleccionar la tecnología más compleja y moderna disponible.", "Dejar que el equipo de ventas decida al azar."], correct: 0, explanation: "Compara el valor neto, costos y riesgos de las opciones de solución para emitir una recomendación fundamentada.", pageRef: "BABOK v3, Cap. 7, Sec. 7.6.1", summary: ["Analizar valor y recomendar: Comparar alternativas y recomendar la de mayor valor."] },
    { id: 909, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿qué formatos principales se utilizan para modelar requisitos?", options: ["Matrices, diagramas y texto descriptivo estructurado.", "Exclusivamente código fuente binario compilado.", "Pinturas al óleo y esculturas tridimensionales.", "Grabaciones de voz y partituras musicales."], correct: 0, explanation: "El modelado emplea matrices (tablas uniformes) y diagramas visuales para representar la información.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1.4", summary: ["Formatos de modelado: Matrices, diagramas y texto estructurado."] },
    { id: 910, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué significa que un requisito sea 'Inequívoco' (Unambiguous)?", options: ["Que debe establecerse de tal forma que no existan múltiples interpretaciones y quede claro si se cumple o no.", "Que está escrito en un idioma extranjero desconocido.", "Que se puede leer tanto de izquierda a derecha como de derecha a izquierda.", "Que cambia de significado todos los días."], correct: 0, explanation: "Un requisito inequívoco tiene una sola interpretación clara y permite verificar objetivamente su cumplimiento.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2.1", summary: ["Requisito inequívoco: Una sola interpretación y criterio claro de verificación."] },
    { id: 911, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿qué propósito tiene el modelado de procesos en el análisis de requerimientos?", options: ["Representar visualmente la secuencia de actividades, flujos de trabajo y decisiones de negocio.", "Diseñar la interfaz gráfica de botones en Figma.", "Calcular el impuesto sobre la renta de la empresa.", "Configurar redes de área local (LAN)."], correct: 0, explanation: "Los modelos de procesos clarifican cómo opera el negocio paso a paso.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1", summary: ["Modelado de procesos: Representación visual de secuencias y flujos de trabajo."] },
    { id: 912, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué evalúa la característica de 'Verificable' (Testable) en un requisito?", options: ["Que existan medios y criterios objetivos para comprobar si el requisito se ha cumplido satisfactoriamente.", "Que el software pueda ejecutarse en computadoras cuánticas.", "Que el documento tenga más de mil páginas impresas.", "Que no pueda ser probado bajo ninguna circunstancia."], correct: 0, explanation: "Un requisito verificable permite diseñar pruebas claras para comprobar su correcta implementación.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2", summary: ["Requisito verificable: Permite comprobar objetivamente su cumplimiento mediante pruebas."] },
    { id: 913, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.3), ¿cómo se diferencia la validación de la verificación?", options: ["La verificación comprueba la calidad de la escritura del requisito (el qué); la validación comprueba que aporte valor real al negocio.", "La verificación se hace en código y la validación en papel.", "No existe ninguna diferencia conceptual entre ambas tareas.", "La validación la hacen los desarrolladores y la verificación los clientes."], correct: 0, explanation: "Verificar es hacer el requisito correcto (calidad intrínseca); validar es hacer el requisito correcto para el negocio (valor).", pageRef: "BABOK v3, Cap. 7, Sec. 7.3", summary: ["Verificación (calidad de escritura) vs Validación (aporte de valor al negocio)."] },
    { id: 914, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.4), ¿por qué es importante mantener una 'Arquitectura de Requisitos' coherente?", options: ["Para evitar contradicciones, redundancias y asegurar que todos los componentes encajen como un sistema global.", "Para incrementar el número de errores tipográficos en los documentos.", "Para duplicar el presupuesto operativo del proyecto sin justificación.", "Para ocultar los cambios recientes al equipo técnico."], correct: 0, explanation: "Una arquitectura estructurada previene silos y asegura que los requerimientos funcionen integrados.", pageRef: "BABOK v3, Cap. 7, Sec. 7.4", summary: ["Arquitectura coherente: Previene contradicciones y asegura integración sistémica."] },
    { id: 915, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.5), ¿qué tipos de opciones de solución se pueden evaluar?", options: ["Soluciones hechas a la medida (custom), paquetes comerciales de software (COTS) o servicios externos.", "Únicamente código escrito en lenguaje ensamblador.", "Exclusivamente compra de mobiliario de oficina.", "Dispositivos mecánicos analógicos sin software."], correct: 0, explanation: "El análisis explora desarrollar interno, comprar paquetes comerciales o externalizar servicios.", pageRef: "BABOK v3, Cap. 7, Sec. 7.5", summary: ["Tipos de soluciones: Desarrollos a la medida, software empaquetado (COTS) o servicios."] },
    { id: 916, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "According to BABOK v3 (Sec. 7.6), ¿qué criterios se ponderan al recomendar la solución óptima?", options: ["Valor neto, costos de implementación, riesgos, viabilidad técnica y alineación con objetivos estratégicos.", "Únicamente el color del logotipo corporativo.", "La nacionalidad de los proveedores de hardware.", "El número de páginas de la cotización comercial."], correct: 0, explanation: "La recomendación equilibra el valor comercial frente a los costos y riesgos de cada alternativa.", pageRef: "BABOK v3, Cap. 7, Sec. 7.6", summary: ["Criterios de recomendación: Valor neto, costos, riesgos y alineación estratégica."] },
    { id: 917, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿qué utilidad tienen las matrices de datos en el modelado de requisitos?", options: ["Organizar información compleja, atributos y reglas de negocio de manera uniforme y estructurada.", "Diseñar la interfaz gráfica de usuario en herramientas de prototipado.", "Calcular la nómina salarial de los empleados de la compañía.", "Establecer las políticas de vacaciones del personal."], correct: 0, explanation: "Las matrices permiten cruzar variables, roles y permisos de forma clara y ordenada.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1", summary: ["Matrices en modelado: Organización uniforme de atributos y reglas de negocio complejas."] },
    { id: 918, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué significa que un requisito sea 'Completo' (Complete)?", options: ["Que incluye todas las propiedades, condiciones y comportamientos necesarios para describir plenamente la necesidad.", "Que abarca más de mil páginas de especificaciones técnicas redundantes.", "Que está escrito en un idioma extranjero desconocido.", "Que no necesita ninguna revisión posterior."], correct: 0, explanation: "Un requisito completo no deja vacíos de información críticos para su diseño e implementación.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2", summary: ["Requisito completo: Incluye todas las propiedades y condiciones sin vacíos críticos."] },
    { id: 919, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.3), ¿quiénes validan principalmente que los requisitos entregan valor de negocio?", options: ["Los patrocinadores, usuarios clave y tomadores de decisiones comerciales.", "Exclusivamente los desarrolladores junior de software.", "El personal de soporte técnico de nivel 1.", "Cualquier transeúnte de la calle."], correct: 0, explanation: "Los roles de negocio son quienes validan si la solución resolverá sus necesidades operativas y estratégicas.", pageRef: "BABOK v3, Cap. 7, Sec. 7.3", summary: ["Validadores de valor: Patrocinadores y usuarios clave del negocio."] },
    { id: 920, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.4), ¿qué es un 'Diccionario de Datos' dentro de la arquitectura de requisitos?", options: ["Un repositorio que define el significado, formato, tipo de dato y reglas de todos los elementos de información.", "Un directorio telefónico de la oficina corporativa.", "Una lista de reproducción de música para los empleados.", "Un conjunto de contratos legales firmados con proveedores."], correct: 0, explanation: "El diccionario de datos estandariza los conceptos y estructuras de información utilizadas en los modelos.", pageRef: "BABOK v3, Cap. 7, Sec. 7.4", summary: ["Diccionario de datos: Estandariza significado, formato y reglas de los elementos informativos."] },
    { id: 921, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.5), ¿qué ventajas ofrece adquirir un paquete comercial (COTS) frente a desarrollar a la medida?", options: ["Menor tiempo inicial de entrega y costos iniciales potencialmente reducidos, aunque con menor personalización.", "Control total y absoluto sobre cada línea de código fuente.", "Imposibilidad absoluta de cometer errores de software.", "Eliminación de la necesidad de realizar capacitación a usuarios."], correct: 0, explanation: "Los paquetes COTS aceleran el despliegue a costa de adaptarse a la estructura estándar del software.", pageRef: "BABOK v3, Cap. 7, Sec. 7.5", summary: ["Paquetes COTS: Menor tiempo inicial de entrega a cambio de menor personalización."] },
    { id: 922, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.6), ¿qué se evalúa en el análisis de compensaciones (trade-offs) entre opciones de solución?", options: ["Balancear los costos frente a los beneficios, riesgos y plazos de cada alternativa disponible.", "Elegir siempre la opción más costosa sin importar el resultado.", "Descartar todas las opciones técnicas complejas sin análisis.", "Dejar que el azar decida la tecnología a utilizar."], correct: 0, explanation: "El análisis de compensaciones ayuda a entender qué se gana y qué se sacrifica con cada opción.", pageRef: "BABOK v3, Cap. 7, Sec. 7.6", summary: ["Análisis de trade-offs: Balancear costos, beneficios, riesgos y plazos entre alternativas."] },
    { id: 923, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿qué propósito tiene el modelado de interfaces de usuario (prototipos)?", options: ["Facilitar la visualización y validación temprana del diseño de interacción con los usuarios finales.", "Escribir el código fuente definitivo de la base de datos relacional en SQL.", "Calcular la declaración fiscal de impuestos anuales de la empresa.", "Configurar los servidores de red física."], correct: 0, explanation: "Los prototipos tangibles permiten elicitar y validar requerimientos de experiencia de usuario.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1", summary: ["Modelado de interfaces/prototipos: Visualización y validación temprana de interacción."] },
    { id: 924, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué caracteriza a un requisito 'Consistente' (Consistent)?", options: ["Que no presenta contradicciones ni conflictos con otros requisitos o diseños del conjunto.", "Que cambia de significado todos los días de la semana.", "Que está escrito en un lenguaje de programación obsoleto.", "Que contiene errores de sintaxis intencionales."], correct: 0, explanation: "La consistencia asegura que las reglas de negocio y especificaciones no se contradigan entre sí.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2", summary: ["Requisito consistente: Ausencia de contradicciones o conflictos con otros requerimientos."] },
    { id: 925, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.3), ¿qué ocurre si un requisito verificado no logra pasar la validación de negocio?", options: ["Aunque esté bien escrito y verificado, se descarta o modifica porque no aporta el valor esperado al negocio.", "Se implementa obligatoriamente en producción sin importar las consecuencias.", "Se duplica el presupuesto del proyecto de manera automática.", "Se despide al equipo de desarrollo de software."], correct: 0, explanation: "Un requisito técnicamente perfecto pero inútil para el negocio no debe construirse.", pageRef: "BABOK v3, Cap. 7, Sec. 7.3", summary: ["Fallo en validación: Se descarta o modifica si no aporta valor real al negocio."] },
    { id: 926, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.4), ¿cómo se estructuran los paquetes de requisitos en una arquitectura formal?", options: ["Agrupándolos por dominios funcionales, procesos, componentes de solución o niveles jerárquicos.", "Apilándolos al azar en una carpeta compartida sin orden.", "Escribiéndolos en códigos secretos sin descifrar.", "Imprimiendo hojas de papel sin numeración."], correct: 0, explanation: "Una estructuración temática o jerárquica facilita la navegación y comprensión arquitectónica.", pageRef: "BABOK v3, Cap. 7, Sec. 7.4", summary: ["Estructuración de paquetes: Agrupación por dominios funcionales o niveles jerárquicos."] },
    { id: 927, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.5), ¿qué se debe considerar al evaluar desarrollos internos personalizados (Custom Build)?", options: ["Disponibilidad de talento técnico, costos de mantenimiento a largo plazo y adecuación exacta a las necesidades.", "Comprar licencias de software comercial cerrado estándar.", "Omitir el análisis de arquitectura técnica por completo.", "Reducir los tiempos de entrega a cero días."], correct: 0, explanation: "El desarrollo a la medida ofrece adaptabilidad perfecta pero implica mayores costos de mantenimiento.", pageRef: "BABOK v3, Cap. 7, Sec. 7.5", summary: ["Desarrollo personalizado (Custom): Adaptación perfecta con mayores costos de mantenimiento."] },
    { id: 928, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.6), ¿quiénes deben aprobar la recomendación final de la solución de negocio?", options: ["Los patrocinadores y tomadores de decisiones clave informados por el análisis del BA.", "Únicamente los analistas junior de menor jerarquía.", "El personal de soporte técnico externo de nivel 1.", "Cualquier transeúnte de la calle sin relación con la empresa."], correct: 0, explanation: "La decisión final de inversión y selección recae en los patrocinadores y directivos del negocio.", pageRef: "BABOK v3, Cap. 7, Sec. 7.6", summary: ["Aprobación de recomendación: Patrocinadores y directivos del negocio con base en análisis."] },
    { id: 929, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿qué es un diagrama de casos de uso (Use Case Diagram)?", options: ["Un modelo que muestra la interacción entre los actores externos y las funciones del sistema.", "Un plano físico de construcción de concreto para oficinas.", "Una tabla contable de impuestos corporativos anuales.", "Un registro de nómina salarial de empleados."], correct: 0, explanation: "Los casos de uso modelan cómo los usuarios interactúan con las capacidades del sistema.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1", summary: ["Diagrama de casos de uso: Interacción entre actores externos y funciones del sistema."] },
    { id: 930, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué implica que un requisito sea 'Conciso' (Concise)?", options: ["Que no contiene información innecesaria, superflua o redundante que opaque su comprensión.", "Que tiene una extensión mínima de mil páginas obligatorias.", "Que está escrito en un lenguaje cifrado indescifrable.", "Que cambia de significado todos los días."], correct: 0, explanation: "La concisión elimina texto de relleno para mantener la claridad y precisión de la especificación.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2", summary: ["Requisito conciso: Ausencia de información innecesaria o redundante para mayor claridad."] },
    { id: 931, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.3), ¿qué método se emplea frecuentemente para validar requisitos con los usuarios?", options: ["Revisiones de prototipos, simulaciones operativas y talleres de validación con escenarios de uso.", "Enviar correos electrónicos masivos sin opción de respuesta.", "Ocultar la documentación técnica al equipo de negocio.", "Realizar auditorías fiscales contables."], correct: 0, explanation: "Prototipar y simular escenarios reales ayuda a los usuarios a confirmar si el requerimiento les sirve.", pageRef: "BABOK v3, Cap. 7, Sec. 7.3", summary: ["Métodos de validación: Revisiones de prototipos y simulaciones con escenarios de uso."] },
    { id: 932, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.4), ¿qué beneficio aporta definir relaciones claras dentro de la arquitectura de requisitos?", options: ["Facilitar el análisis de impacto ante cambios futuros y entender cómo se interconectan los elementos.", "Incrementar los errores tipográficos en los documentos formales.", "Duplicar los costos operativos del proyecto sin justificación.", "Ocultar información clave a los desarrolladores de software."], correct: 0, explanation: "Las relaciones arquitectónicas aseguran que cualquier modificación se evalúe de manera sistémica.", pageRef: "BABOK v3, Cap. 7, Sec. 7.4", summary: ["Relaciones arquitectónicas: Facilitan análisis de impacto y comprensión de interconexiones."] },
    { id: 933, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.5), ¿qué se evalúa al analizar la viabilidad técnica de una opción de solución?", options: ["Si la tecnología propuesta es compatible, madura y capaz de integrarse con los sistemas existentes de la empresa.", "Si el logotipo corporativo tiene colores atractivos para los clientes.", "Si el edificio de oficinas tiene suficientes pisos de altura física.", "Si los empleados prefieren café o té por la mañana."], correct: 0, explanation: "La viabilidad técnica comprueba la integración y el soporte tecnológico de la alternativa.", pageRef: "BABOK v3, Cap. 7, Sec. 7.5", summary: ["Viabilidad técnica: Compatibilidad, madurez e integración con sistemas existentes."] },
    { id: 934, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "According to BABOK v3 (Sec. 7.6), ¿por qué es importante documentar los motivos que fundamentan la recomendación de solución?", options: ["Para asegurar transparencia, justificar la inversión ante los patrocinadores y facilitar auditorías futuras.", "Para ocultar los errores de análisis cometidos por el equipo.", "Para incrementar el tamaño de los documentos impresos en papel.", "Para retrasar la entrega del software de manera indefinida."], correct: 0, explanation: "Documentar la justificación respalda la toma de decisiones gerenciales frente al consejo directivo.", pageRef: "BABOK v3, Cap. 7, Sec. 7.6", summary: ["Justificación de recomendación: Transparencia y respaldo de la inversión ante patrocinadores."] },
    { id: 935, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.1), ¿qué muestra un diagrama de entidad-relación (ERD) en el modelado de datos?", options: ["Las entidades de información del negocio, sus atributos y las relaciones estructurales entre ellas.", "El plano arquitectónico de construcción de concreto del edificio.", "El organigrama jerárquico de directores ejecutivos.", "El flujo de caja financiero trimestral de la empresa."], correct: 0, explanation: "El modelo ERD estructura conceptual y lógicamente los datos que manejará la solución.", pageRef: "BABOK v3, Cap. 7, Sec. 7.1", summary: ["Modelo ERD: Entidades de información, atributos y relaciones estructurales."] },
    { id: 936, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.2), ¿qué significa que un requisito sea 'Entendible' (Understandable)?", options: ["Que está expresado en un lenguaje claro y accesible para la audiencia que lo va a leer o implementar.", "Que solo puede ser descifrado por expertos en física cuántica avanzada.", "Que está escrito en un idioma extranjero desconocido.", "Que contiene contradicciones intencionales."], correct: 0, explanation: "La claridad del lenguaje previene interpretaciones erróneas por parte de analistas, desarrolladores y testers.", pageRef: "BABOK v3, Cap. 7, Sec. 7.2", summary: ["Requisito entendible: Expresado en lenguaje claro y accesible para la audiencia."] },
    { id: 937, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.3), ¿quién tiene la responsabilidad final de garantizar que los requisitos estén validados?", options: ["El analista de negocios en colaboración con los patrocinadores y stakeholders de negocio.", "Exclusivamente los ingenieros de pruebas de software junior.", "El personal de soporte técnico de nivel 1.", "Cualquier transeúnte de la calle sin relación con la iniciativa."], correct: 0, explanation: "El BA facilita y documenta la validación, asegurando el consenso con los dueños del negocio.", pageRef: "BABOK v3, Cap. 7, Sec. 7.3", summary: ["Responsabilidad de validación: Analista de negocios facilitando consenso con stakeholders."] },
    { id: 938, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.4), ¿qué beneficio aporta una arquitectura de requisitos bien mantenida ante cambios de alcance?", options: ["Permite aislar el impacto del cambio y actualizar únicamente los componentes afectados sin romper el sistema global.", "Obliga a reescribir todo el código fuente del proyecto desde cero cada semana.", "Elimina la necesidad de gestionar presupuestos financieros.", "Duplica los costos operativos de la empresa de manera inmediata."], correct: 0, explanation: "Una estructura modular y arquitectónicamente sólida absorbe los cambios de forma controlada.", pageRef: "BABOK v3, Cap. 7, Sec. 7.4", summary: ["Beneficio arquitectónico ante cambios: Aislar impactos y actualizar componentes afectados."] },
    { id: 939, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.5), ¿qué se analiza al estudiar el riesgo de proveedor en opciones de solución externas?", options: ["La estabilidad financiera, la reputación, el soporte técnico y la dependencia a largo plazo del proveedor del software.", "El color del logotipo corporativo del proveedor.", "La velocidad de los servidores de la competencia.", "El menú de la cafetería del proveedor."], correct: 0, explanation: "Evaluar al proveedor previene riesgos de quiebra, desatención o aumentos imprevistos de costos de licencia.", pageRef: "BABOK v3, Cap. 7, Sec. 7.5", summary: ["Riesgo de proveedor en soluciones externas: Estabilidad, soporte y dependencia a largo plazo."] },
    { id: 940, chapter: 6, chapterTitle: "Cap. 6: Análisis y Definición de Diseño", q: "Según el BABOK v3 (Sec. 7.6), ¿qué relación guarda la recomendación de solución con el 'Valor Potencial' analizado previamente?", options: ["La solución recomendada debe ser aquella que demuestre maximizar el valor potencial neto frente a sus costos y riesgos.", "Debe elegirse siempre la opción más costosa y compleja sin importar el valor obtenido.", "No guarda ninguna relación con el análisis estratégico previo.", "El valor potencial se ignora por completo al momento de recomendar."], correct: 0, explanation: "La recomendación conecta directamente la estrategia de valor con la opción técnica seleccionada.", pageRef: "BABOK v3, Cap. 7, Sec. 7.6", summary: ["Recomendación y valor potencial: Seleccionar la opción que maximice el valor neto frente a costos y riesgos."] },

];